impl Way {
    fn len(&self) -> f64 {
        self.pts.windows(2).map(|w| ((w[1].0 - w[0].0).powi(2) + (w[1].1 - w[0].1).powi(2)).sqrt()).sum()
    }
    /// Point and unit tangent at distance s along.
    fn at(&self, s: f64) -> ((f64, f64), (f64, f64)) {
        let mut s = s;
        for w in self.pts.windows(2) {
            let (dx, dy) = (w[1].0 - w[0].0, w[1].1 - w[0].1);
            let l = (dx * dx + dy * dy).sqrt();
            if s <= l {
                return ((w[0].0 + dx * s / l, w[0].1 + dy * s / l), (dx / l, dy / l));
            }
            s -= l;
        }
        let n = self.pts.len();
        let (a, b) = (self.pts[n - 2], self.pts[n - 1]);
        let l = ((b.0 - a.0).powi(2) + (b.1 - a.1).powi(2)).sqrt();
        (b, ((b.0 - a.0) / l, (b.1 - a.1) / l))
    }
    /// Deck top over the ground at s (0 for an avenue).
    fn deck(&self, s: f64, len: f64) -> f64 {
        if self.kind == WayKind::Avenue {
            return 0.0;
        }
        // each end eases from its own height to the middle's over RAMP_LEN (smoothstepped); the
        // nearer end decides
        let e = |t: f64| {
            let t = t.clamp(0.0, 1.0);
            t * t * (3.0 - 2.0 * t)
        };
        // (a ramp level at one end eases over its whole length from the other end, if that is
        // shorter than two ramp lengths: the cloverleaf's loops, no step at their middle)
        if self.h0 == self.top && self.h1 != self.top {
            return self.h1 + (self.top - self.h1) * e((len - s) / RAMP_LEN.min(len));
        }
        if self.h1 == self.top && self.h0 != self.top {
            return self.h0 + (self.top - self.h0) * e(s / RAMP_LEN.min(len));
        }
        if s < len - s {
            self.h0 + (self.top - self.h0) * e(s / RAMP_LEN)
        } else {
            self.h1 + (self.top - self.h1) * e((len - s) / RAMP_LEN)
        }
    }
    /// Distance from the centre line to a point (unsigned), if within `reach`.
    fn dist(&self, x: f64, y: f64, reach: f64) -> Option<f64> {
        let mut best = f64::MAX;
        for w in self.pts.windows(2) {
            let (ax, ay, bx, by) = (w[0].0, w[0].1, w[1].0, w[1].1);
            if x < ax.min(bx) - reach || x > ax.max(bx) + reach || y < ay.min(by) - reach || y > ay.max(by) + reach {
                continue;
            }
            let (dx, dy) = (bx - ax, by - ay);
            let t = (((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)).clamp(0.0, 1.0);
            best = best.min(((x - ax - dx * t).powi(2) + (y - ay - dy * t).powi(2)).sqrt());
        }
        (best < reach).then_some(best)
    }
}

/// Ground kept clear inside the interchanges (landscaped, nothing built or parked): circles in
/// the city's plane, x, y, radius (globe.rchit C_CLEAR the same).
const CLEAR: &[(f64, f64, f64)] = &[(-3061.0, -1660.0, 0.0)];

fn in_clear(x: f64, y: f64) -> bool {
    CLEAR.iter().any(|&(cx, cy, r)| (x - cx).powi(2) + (y - cy).powi(2) < r * r)
}

/// Is the city-plane point on one of the roads (within its half width plus `pad`)?
fn on_way(x: f64, y: f64, pad: f64) -> bool {
    WAYS.iter().any(|w| w.dist(x, y, w.half + pad).is_some())
}

/// Highway and ramp decks, the traffic on them and on the avenues, the avenues' median palms,
/// whose feet lie in tile `id` (box `lo`..`hi` in the city's plane).
#[allow(clippy::too_many_arguments)]
fn way_items(k: usize, terrain: &Terrain, sp: &Species, id: TileId, tile: &mut TreeTile, lvl: u8, lo: (f64, f64), hi: (f64, f64)) {
    let _t = Timer(2, std::time::Instant::now());
    let (kinds, _) = car_kinds(&sp.buildings);
    let decks: Vec<&ArchRef> = sp.buildings.iter().filter(|a| a.class == Class::Highway).collect();
    if decks.len() < 2 || kinds.len() < 6 {
        return;
    }
    for (wi, w) in WAYS.iter().enumerate() {
        let len = w.len();
        let wl = wi as i64;
        // (ramps: a 6 m piece every 5 m, so the loops' curves are followed; else 20 m pieces)
        let step = if w.kind == WayKind::Ramp && decks.len() >= 3 { 5.0 } else { 20.0 };
        let mut s = step * 0.5;
        let mut n = 0u32;
        while s < len {
            let sc = s;
            let ((x, y), (tx, ty)) = w.at(sc);
            let seg = n;
            n += 1;
            s += step;
            if x < lo.0 - 40.0 || x > hi.0 + 40.0 || y < lo.1 - 40.0 || y > hi.1 + 40.0 {
                continue;
            }
            // (the heading from the curve's own tangent over the piece)
            let (pa, _) = w.at((sc - step * 0.5).max(0.0));
            let (pb, _) = w.at((sc + step * 0.5).min(len));
            let yaw = if step < 20.0 { (pb.1 - pa.1).atan2(pb.0 - pa.0) } else { ty.atan2(tx) };
            let h = w.deck(sc, len);
            let slope = (w.deck(sc + step * 0.5, len) - w.deck(sc - step * 0.5, len)) / step;
            let pitch = slope.atan();
            let g = ground_world(k, terrain, x, y);
            // (traffic and palms as before: one chance per 20 m)
            let every = (20.0 / step) as u32;
            if w.kind != WayKind::Avenue && lvl <= 2 {
                let base = if w.kind == WayKind::Highway { 0 } else if step < 20.0 { 2 } else { 1 };
                // where a ramp runs alongside the highway (and the highway alongside a ramp), that
                // side's parapet is left off: the decks meet at the gore (local +z is the right)
                let mut open = 0;
                if decks.len() >= 9 {
                    let (half, other_half, other) = if w.kind == WayKind::Highway { (15.0, 5.5, WayKind::Ramp) } else { (5.5, 15.0, WayKind::Highway) };
                    for side in [-1.0f64, 1.0] {
                        let (px, py) = (x + ty * side * (half + other_half), y - tx * side * (half + other_half));
                        let beside = WAYS.iter().any(|o| o.kind == other && o.dist(px, py, 3.0).is_some());
                        if beside {
                            open = side as i32;
                        }
                    }
                }
                let idx = if open == 0 { base } else { 3 + base * 2 + if open < 0 { 0 } else { 1 } };
                let deck = decks[idx];
                put_world(k, sp, deck, x, y, g + h - DECK_TOP, yaw, pitch, bh(wl, seg as i64, 11), id, tile);
            }
            if lvl != 0 || seg % every != 0 {
                continue;
            }
            let seg = seg / every;
            // traffic: right-hand, lanes by kind; a car now and then in each lane per 20 m
            let lanes: &[f64] = match w.kind {
                WayKind::Highway => &[-9.4, -5.8, -2.2, 2.2, 5.8, 9.4],
                WayKind::Ramp => &[0.0],
                WayKind::Avenue => &[-6.6, -3.2, 3.2, 6.6],
            };
            for (li, &off) in lanes.iter().enumerate() {
                let salt = 100 + li as i64;
                if bu(wl, seg as i64 * 16 + salt, 12) > if w.kind == WayKind::Highway { 0.55 } else { 0.35 } {
                    continue;
                }
                let along = (bu(wl, seg as i64 * 16 + salt, 13) - 0.5) * 16.0;
                // (the right of the direction of travel is +off: x right = (ty, -tx))
                let (cx, cy) = (x + tx * along + ty * off, y + ty * along - tx * off);
                if w.kind == WayKind::Avenue && water_world(k, terrain, cx, cy) {
                    continue;
                }
                let back = off < 0.0 || (w.kind == WayKind::Ramp && bu(wl, seg as i64, 14) < 0.0);
                let kind = if bu(wl, seg as i64 * 16 + salt, 15) < 0.05 { 5 } else { (bh(wl, seg as i64 * 16 + salt, 16) % 5) as usize };
                let cyaw = yaw + if back { std::f64::consts::PI } else { 0.0 };
                let cp = if back { -pitch } else { pitch };
                put_world(k, sp, kinds[kind], cx, cy, ground_world(k, terrain, cx, cy) + h + 0.02, cyaw, cp, bh(wl, seg as i64 * 16 + salt, 17), id, tile);
            }
            // the avenues' medians: a palm every 20 m
            if w.kind == WayKind::Avenue && !sp.palms.is_empty() && !water_world(k, terrain, x, y) {
                let vid = sp.palms[(bh(wl, seg as i64, 18) as usize) % sp.palms.len()];
                put_world_v(k, sp, vid, x, y, g - 0.1, bu(wl, seg as i64, 19) * std::f64::consts::TAU, 0.9 + 0.3 * bu(wl, seg as i64, 20), bh(wl, seg as i64, 21), id, tile);
            }
        }
    }
}

fn ground_world(k: usize, terrain: &Terrain, x: f64, y: f64) -> f64 {
    let (la, lo) = to_lat_lon_world(k, x, y);
    terrain.height(la, lo).max(0.0) as f64
}

fn water_world(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    let (la, lo) = to_lat_lon_world(k, x, y);
    sea_level_water(terrain, la, lo)
}

fn to_lat_lon_world(k: usize, x: f64, y: f64) -> (f64, f64) {
    let f = &frames()[k];
    lat_lon(f.centre + f.east * x + f.north * y)
}

/// Is the city-plane point's foot in tree tile `id`?
fn in_tile_world(k: usize, x: f64, y: f64, id: TileId) -> Option<DVec3> {
    let (lat, lon) = to_lat_lon_world(k, x, y);
    let d = super::tiles::dir_from_lat_lon(lat, lon);
    let (face, u, v) = super::forest::dir_to_face_uv(d);
    let cells = 1u64 << id.level;
    let to_cell = |c: f64| (((c + 1.0) * 0.5 * cells as f64).floor() as i64).clamp(0, cells as i64 - 1) as u32;
    (face == id.face && to_cell(u) == id.x && to_cell(v) == id.y).then_some(d)
}

/// Archetype `r` at a city-plane point, base height h, heading `yaw`, tilted up by `pitch`.
#[allow(clippy::too_many_arguments)]
fn put_world(k: usize, sp: &Species, r: &ArchRef, x: f64, y: f64, h: f64, yaw: f64, pitch: f64, seed: u32, id: TileId, tile: &mut TreeTile) {
    let Some(d) = in_tile_world(k, x, y, id) else { return };
    if tile.recs.len() >= MAX_PER_TILE {
        return;
    }
    let up = d;
    let east = DVec3::Z.cross(up).normalize();
    let north = up.cross(east);
    let fx = east * yaw.cos() + north * yaw.sin();
    let ax = fx * pitch.cos() + up * pitch.sin();
    let ay = up * pitch.cos() - fx * pitch.sin();
    let az = ax.cross(ay);
    let t = d * (R_EARTH + h) - tile.center;
    let rows = [[ax.x, ay.x, az.x, t.x], [ax.y, ay.y, az.y, t.y], [ax.z, ay.z, az.z, t.z]];
    push_rec(tile, rows, super::forest::rec_data(r.variant, (1 + seed % 8190) << 8), &sp.infos[r.variant]);
}

/// A plant variant at a city-plane point, standing upright.
#[allow(clippy::too_many_arguments)]
fn put_world_v(k: usize, sp: &Species, vid: usize, x: f64, y: f64, h: f64, yaw: f64, sc: f64, seed: u32, id: TileId, tile: &mut TreeTile) {
    let Some(d) = in_tile_world(k, x, y, id) else { return };
    if tile.recs.len() >= MAX_PER_TILE {
        return;
    }
    let up = d;
    let east = DVec3::Z.cross(up).normalize();
    let north = up.cross(east);
    let fx = east * yaw.cos() + north * yaw.sin();
    let z = fx.cross(up);
    let (fx, y2, z) = (fx * sc, up * sc, z * sc);
    let t = d * (R_EARTH + h) - tile.center;
    let rows = [[fx.x, y2.x, z.x, t.x], [fx.y, y2.y, z.y, t.y], [fx.z, y2.z, z.z, t.z]];
    push_rec(tile, rows, super::forest::rec_data(vid, (1 + seed % 8190) << 8), &sp.infos[vid]);
}

/// The city whose plan covers lat / lon, and the point in its plan (m, before the warp).
fn city_at(lat: f64, lon: f64) -> Option<(usize, f64, f64)> {
    let (k, x, y) = city_at_world(lat, lon)?;
    let (px, py) = to_plan(x, y);
    Some((k, px, py))
}

/// The city covering lat / lon and the point in its plane (m), without the plan's warp.
fn city_at_world(lat: f64, lon: f64) -> Option<(usize, f64, f64)> {
    CITIES.iter().enumerate().find_map(|(k, c)| {
        // (a quick test first)
        if (lat - c.lat).abs() > c.radius / 100_000.0 || (lon - c.lon).abs() * c.lat.to_radians().cos() > c.radius / 100_000.0 {
            return None;
        }
        let (x, y) = plane(k, super::tiles::dir_from_lat_lon(lat, lon));
        (x * x + y * y < c.radius * c.radius).then_some((k, x, y))
    })
}

/// A plan point's latitude and longitude (through the warp).
fn to_lat_lon(k: usize, x: f64, y: f64) -> (f64, f64) {
    let (wx, wy) = to_world(x, y);
    to_lat_lon_world(k, wx, wy)
}

/// How central a place is: 1 in a downtown core, falling off with distance.
fn density(k: usize, x: f64, y: f64) -> f64 {
    CITIES[k]
        .cores
        .iter()
        .zip(&frames()[k].cores)
        .map(|(c, &(cx, cy))| {
            let d2 = ((x - cx).powi(2) + (y - cy).powi(2)) / (c.radius * c.radius);
            c.strength * (-d2).exp()
        })
        .fold(0.0, f64::max)
}

fn density_at_block(k: usize, i: i64, j: i64) -> f64 {
    let (x0, y0, w, h) = interior(i, j);
    density(k, x0 + w * 0.5, y0 + h * 0.5)
}

fn block_zone(k: usize, i: i64, j: i64) -> u32 {
    let (x0, y0, w, h) = interior(i, j);
    let z = zone(density(k, x0 + w * 0.5, y0 + h * 0.5) + (bu(i, j, 1) - 0.5) * 0.12);
    // shops and walk-ups along the arterials, between the house blocks
    if z == 0 && (art_x(i) || art_x(i + 1) || art_y(j) || art_y(j + 1)) && bu(i, j, 6) < 0.6 {
        1
    } else {
        z
    }
}

/// What the terrain shader needs to draw the plan (globe.rchit cityGround).
pub struct ShaderCity {
    pub centre: DVec3,
    pub east: DVec3,
    pub north: DVec3,
    /// block x, block y, radius, number of cores
    pub params: [f32; 4],
    /// cores: x, y in the plane, strength, radius
    pub cores: [[f32; 4]; MAX_CORES],
}

/// The city nearest the camera (ECEF), if it is near enough to matter.
pub fn shader_city(cam: DVec3) -> Option<ShaderCity> {
    let d = cam.normalize();
    let eye = (cam.length() - R_EARTH).max(0.0);
    let k = (0..CITIES.len())
        .filter(|&k| (d * R_EARTH - frames()[k].centre).length() < CITIES[k].radius * 3.0 + eye * 4.0)
        .min_by(|&a, &b| (d - frames()[a].centre.normalize()).length().total_cmp(&(d - frames()[b].centre.normalize()).length()))?;
    let (c, f) = (&CITIES[k], &frames()[k]);
    let mut cores = [[0.0f32; 4]; MAX_CORES];
    for (n, (core, &(x, y))) in c.cores.iter().zip(&f.cores).take(MAX_CORES).enumerate() {
        cores[n] = [x as f32, y as f32, core.strength as f32, core.radius as f32];
    }
    Some(ShaderCity { centre: f.centre, east: f.east, north: f.north, params: [BX as f32, BY as f32, c.radius as f32, c.cores.len().min(MAX_CORES) as f32], cores })
}

// ---- rivers and canals carved through the city's land (as Miami's own river and canals
// wind through it): sinuous channels in the city's plane. The land cover reads them as water
// (landcover.rs class_at asks canal_at), and the ground under them is cut below the sea
// (ground_cap), so the terrain's shoreline field, seawalls, the plan's buildings, bridges,
// docks and boats all follow from that one place.

struct Channel {
    /// from, to (city plane, m), half width (m), meander amplitude (m) and wavelength (m)
    a: (f64, f64),
    b: (f64, f64),
    half: f64,
    amp: f64,
    wave: f64,
}

const CHANNELS: &[Channel] = &[
    // two winding rivers from the bay west through the mainland
    Channel { a: (-1650.0, 2350.0), b: (-7200.0, 3900.0), half: 55.0, amp: 170.0, wave: 1500.0 },
    Channel { a: (-1900.0, -3300.0), b: (-7400.0, -2300.0), half: 45.0, amp: 150.0, wave: 1300.0 },
    // canals branching off them, between the built-up islands they make
    Channel { a: (-4300.0, 2950.0), b: (-4500.0, 7600.0), half: 24.0, amp: 70.0, wave: 900.0 },
    Channel { a: (-5700.0, 3400.0), b: (-5600.0, 7400.0), half: 22.0, amp: 60.0, wave: 1000.0 },
    Channel { a: (-2600.0, 2550.0), b: (-2400.0, 6800.0), half: 22.0, amp: 80.0, wave: 1100.0 },
    Channel { a: (-4600.0, -2950.0), b: (-4900.0, -6800.0), half: 22.0, amp: 70.0, wave: 950.0 },
    // the river between downtown and Brickell: from the bay west, broad (180 m) and in long
    // S-bends, as the Miami River leads the eye to the towers
    Channel { a: (-1250.0, -1150.0), b: (-7600.0, 250.0), half: 90.0, amp: 260.0, wave: 2600.0 },
    // a back channel north of it round a wooded island (from the river and back to it)
    Channel { a: (-3147.0, -440.0), b: (-3420.0, -250.0), half: 34.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-3420.0, -250.0), b: (-3760.0, -235.0), half: 34.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-3760.0, -235.0), b: (-3938.0, -560.0), half: 34.0, amp: 0.0, wave: 1000.0 },
    // where the river meets the city's inner bay: a lagoon, arms of water north and south of
    // the river joined at their ends, the land between them wooded islands (ISLAND_PARKS)
    Channel { a: (-4350.0, -140.0), b: (-2900.0, -170.0), half: 150.0, amp: 60.0, wave: 1400.0 },
    Channel { a: (-4350.0, -1180.0), b: (-2900.0, -1140.0), half: 150.0, amp: 70.0, wave: 1300.0 },
    Channel { a: (-4350.0, -140.0), b: (-4350.0, -1180.0), half: 120.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-2900.0, -170.0), b: (-2900.0, -1140.0), half: 120.0, amp: 0.0, wave: 1000.0 },
    // a canal looping south off it round a peninsula
    Channel { a: (-2690.0, -720.0), b: (-2620.0, -1080.0), half: 28.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-2620.0, -1080.0), b: (-2900.0, -1260.0), half: 28.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-2900.0, -1260.0), b: (-3200.0, -1120.0), half: 28.0, amp: 0.0, wave: 1000.0 },
    Channel { a: (-3200.0, -1120.0), b: (-3260.0, -560.0), half: 28.0, amp: 0.0, wave: 1000.0 },
    // Miami Beach's west side: residential canals behind the barrier island
    Channel { a: (3350.0, 900.0), b: (3550.0, 6200.0), half: 25.0, amp: 60.0, wave: 1400.0 },
    // and through the land at the west end of the beach, from the bay to the bay
    Channel { a: (2350.0, 300.0), b: (3300.0, 1900.0), half: 32.0, amp: 110.0, wave: 1000.0 },
    Channel { a: (2300.0, 1300.0), b: (3900.0, 600.0), half: 26.0, amp: 80.0, wave: 900.0 },
];

struct ChannelIndex {
    /// segments (ax, ay, bx, by, half), and per 100 m cell of the plane the segments near it
    segs: Vec<(f64, f64, f64, f64, f64)>,
    cells: std::collections::HashMap<(i64, i64), Vec<u32>>,
}

const CH_CELL: f64 = 100.0;

fn channels() -> &'static ChannelIndex {
    static I: std::sync::OnceLock<ChannelIndex> = std::sync::OnceLock::new();
    I.get_or_init(|| {
        let mut segs = Vec::new();
        for c in CHANNELS {
            let (dx, dy) = (c.b.0 - c.a.0, c.b.1 - c.a.1);
            let len = (dx * dx + dy * dy).sqrt();
            let (tx, ty) = (dx / len, dy / len);
            let (nx, ny) = (-ty, tx);
            let n = (len / 12.0).ceil() as usize;
            let at = |t: f64| {
                let s = t * len;
                // a meander of two waves, easing in from the mouth
                let ease = (s / 300.0).min(1.0);
                let off = ease * (c.amp * (std::f64::consts::TAU * s / c.wave).sin() + 0.35 * c.amp * (std::f64::consts::TAU * s / (c.wave * 0.43) + 1.3).sin());
                (c.a.0 + tx * s + nx * off, c.a.1 + ty * s + ny * off)
            };
            let mut p = at(0.0);
            for k in 1..=n {
                let q = at(k as f64 / n as f64);
                segs.push((p.0, p.1, q.0, q.1, c.half));
                p = q;
            }
        }
        let mut cells: std::collections::HashMap<(i64, i64), Vec<u32>> = std::collections::HashMap::new();
        for (i, s) in segs.iter().enumerate() {
            let r = s.4 + 10.0;
            let (x0, x1) = (s.0.min(s.2) - r, s.0.max(s.2) + r);
            let (y0, y1) = (s.1.min(s.3) - r, s.1.max(s.3) + r);
            for cy in (y0 / CH_CELL).floor() as i64..=(y1 / CH_CELL).floor() as i64 {
                for cx in (x0 / CH_CELL).floor() as i64..=(x1 / CH_CELL).floor() as i64 {
                    cells.entry((cx, cy)).or_default().push(i as u32);
                }
            }
        }
        ChannelIndex { segs, cells }
    })
}

/// Signed distance (m) from the city-plane point to the nearest channel's bank (< 0: in it).
fn channel_dist(x: f64, y: f64) -> f64 {
    let ix = channels();
    let Some(list) = ix.cells.get(&((x / CH_CELL).floor() as i64, (y / CH_CELL).floor() as i64)) else { return f64::MAX };
    let mut best = f64::MAX;
    for &i in list {
        let (ax, ay, bx, by, half) = ix.segs[i as usize];
        let (dx, dy) = (bx - ax, by - ay);
        let t = (((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)).clamp(0.0, 1.0);
        let d = ((x - ax - dx * t).powi(2) + (y - ay - dy * t).powi(2)).sqrt() - half;
        best = best.min(d);
    }
    best
}

/// The direction (unit, world plane) of the river or canal nearest the point, if one is near.
fn channel_dir(x: f64, y: f64) -> Option<(f64, f64)> {
    let ix = channels();
    let list = ix.cells.get(&((x / CH_CELL).floor() as i64, (y / CH_CELL).floor() as i64))?;
    let mut best = (f64::MAX, (0.0, 0.0));
    for &i in list {
        let (ax, ay, bx, by, half) = ix.segs[i as usize];
        let (dx, dy) = (bx - ax, by - ay);
        let t = (((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)).clamp(0.0, 1.0);
        let d = ((x - ax - dx * t).powi(2) + (y - ay - dy * t).powi(2)).sqrt() - half;
        if d < best.0 {
            let l = (dx * dx + dy * dy).sqrt();
            best = (d, (dx / l, dy / l));
        }
    }
    (best.0 < 30.0).then_some(best.1)
}

/// Is lat / lon in one of the cities' rivers or canals? (landcover.rs: the land cover's water)
pub fn canal_at(lat: f64, lon: f64) -> bool {
    // (a cheap box first: this is asked for every land cover sample on Earth)
    if !(25.60..25.96).contains(&lat) || !(-80.36..-79.98).contains(&lon) {
        return false;
    }
    match city_at_world(lat, lon) {
        Some((_, x, y)) => channel_dist(x, y) < 0.0,
        None => false,
    }
}

/// Terrain heights in a city: the 30 m elevation is a surface model (it has the real city's
/// buildings and trees in it, blurred); there the ground is the plain the city stands on, a few
/// metres above the sea. Water and the sea floor stay as they are.
pub fn ground_cap(lat: f64, lon: f64) -> Option<f32> {
    let (k, x, y) = city_at_world(lat, lon)?;
    // the rivers' and canals' beds, below the sea (their banks a few metres out)
    // (sloped, not a step: the bed rises over its last 6 m to just under the water at the bank,
    // the land comes down to it over 4 m; a step the terrain's mesh cut into a sawtooth)
    let cd = channel_dist(x, y);
    if cd < 0.0 {
        return Some((-2.5 + 2.3 * (1.0 + cd / 6.0).clamp(0.0, 1.0)) as f32);
    }
    if cd < 4.0 {
        return Some((-0.2 + 2.7 * cd / 4.0) as f32);
    }
    let r = (x * x + y * y).sqrt() / CITIES[k].radius;
    // fade back to the data over the last fifth of the radius
    let t = ((r - 0.8) / 0.2).clamp(0.0, 1.0);
    Some(2.5 + 400.0 * (t * t) as f32)
}

/// One building of the plan: archetype, centre (plane m), yaw in quarter turns, scale.
#[derive(Clone)]
struct Placed {
    arch: usize,
    x: f64,
    y: f64,
    quarter: u32,
    scale: f64,
    /// footprint half extents in the plane after the turn
    hx: f64,
    hy: f64,
}

/// How built-up the land cover says a place is, for the plan: in a Florida city the yards and
/// street trees make much of the housing read as tree cover and grassland, so they count half
/// (globe.rchit cityGround the same).
fn urban_share(f: &[f32; lc::GROUPS]) -> f32 {
    (f[4] + 0.5 * (f[lc::TREE] + f[lc::GRASS])).min(1.0)
}

/// `urban_share` over a square of `size` m round lat / lon; mapped water above sea level counts
/// as built (globe.rchit draws those ponds as the city's land, lots and all).
fn built_share(terrain: &Terrain, la: f64, lo: f64, size: f64) -> f32 {
    let Some(f) = terrain.cover.fractions(la, lo, size) else { return 0.0 };
    let pond = f[lc::WATER] > 0.0 && !sea_level_water(terrain, la, lo);
    (urban_share(&f) + if pond { f[lc::WATER] } else { 0.0 }).min(1.0)
}

/// Places whose waterfront always has a group of towers (lat, lon, reach m): the west end
/// of the beach by the canal mouth, and the islands across the bay.
const TOWER_SPOTS: &[(f64, f64, f64)] = &[
    (25.78599, -80.14275, 200.0),
    (25.7840, -80.1620, 260.0),
    (25.7790, -80.1700, 260.0),
    (25.7935, -80.1600, 260.0),
];

/// Wooded islands, nothing built on them (world plane rectangles: x0, y0, x1, y1): the land
/// the lagoon's arms and the river leave between them.
const ISLAND_PARKS: &[(f64, f64, f64, f64)] = &[(-4230.0, -1030.0, -3020.0, -290.0)];

/// Is block (i, j) of zone z a surface car park round its buildings? (A third of the walk-up
/// blocks, a few mid-rise ones; globe.rchit cityGround the same.) The rest are lawns, paths
/// and shade trees.
fn parking_block(z: u32, i: i64, j: i64) -> bool {
    (z == 1 && bu(i, j, 8) < 0.08) || (z == 2 && bu(i, j, 3) < 0.04)
}

/// Is the plane point on built-up, dry ground? `strict`: also needs enough built-up land.
fn buildable(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    let (wx, wy) = to_world(x, y);
    // (and 10 m back from the rivers' and canals' banks: the promenade, globe.rchit)
    if on_way(wx, wy, 1.0) || in_clear(wx, wy) || channel_dist(wx, wy) < 10.0 {
        return false;
    }
    let (la, lo) = to_lat_lon(k, x, y);
    // (a pond above sea level is land in a city: globe.rchit draws it so)
    !matches!(terrain.cover.class_group(la, lo), Some(lc::WETLAND) | None) && !sea_level_water(terrain, la, lo)
}

/// The buildings of block (i, j) (land permitting). Only buildings at least `need` m tall are
/// worked out; every choice comes from hashes of the block and lot, so a lot has the same
/// building whoever asks.
fn block(k: usize, archs: &[ArchRef], terrain: &Terrain, i: i64, j: i64, need: f32) -> Vec<Placed> {
    // (every block is asked for by the tiles round it and by each of its uses: per thread, the
    // answer is kept)
    let key = (k, i, j, need.to_bits());
    if let Some(v) = BLOCKS.with(|c| c.borrow().get(&key).cloned()) {
        return v;
    }
    let v = block_plan(k, archs, terrain, i, j, need);
    BLOCKS.with(|c| {
        let mut c = c.borrow_mut();
        if c.len() > 200_000 {
            c.clear();
        }
        c.insert(key, v.clone());
    });
    v
}

thread_local! {
    static BLOCKS: std::cell::RefCell<std::collections::HashMap<(usize, i64, i64, u32), Vec<Placed>>> = Default::default();
}

fn block_plan(k: usize, archs: &[ArchRef], terrain: &Terrain, i: i64, j: i64, need: f32) -> Vec<Placed> {
    let _t = Timer(4, std::time::Instant::now());
    let mut out = Vec::new();
    let (x0, y0, w, h) = interior(i, j);
    let z = block_zone(k, i, j);
    {
        let (cx, cy) = to_world(x0 + w * 0.5, y0 + h * 0.5);
        if ISLAND_PARKS.iter().any(|&(ax, ay, bx, by)| (ax..bx).contains(&cx) && (ay..by).contains(&cy)) {
            return out;
        }
    }
    // (the zones below the cores hold nothing that tall)
    let tallest = |cls: &[Class]| archs.iter().filter(|a| cls.contains(&a.class)).map(|a| a.height).fold(0.0f32, f32::max);
    let classes: &[Class] = match z {
        3 => &[Class::Tower, Class::Tower, Class::Tower, Class::MidRise],
        // (a tower in the mid-rise zone only next to a core)
        2 if density_at_block(k, i, j) > 0.38 => &[Class::MidRise, Class::MidRise, Class::Tower, Class::LowRise],
        2 => &[Class::MidRise, Class::MidRise, Class::MidRise, Class::LowRise, Class::MidRise],
        1 => &[Class::LowRise, Class::MidRise, Class::MidRise],
        _ => &[Class::House],
    };
    // a waterfront mid-rise block now and then has a slender tower of 25-40 storeys at its
    // corner, as Miami's residential towers line its bay and river (its first lot)
    // (they come in clusters: in three 3 x 3 block cells in five a few waterfront blocks have one,
    // elsewhere hardly any, so some islands have a few together and some none)
    let (bla, blo) = to_lat_lon(k, x0 + w * 0.5, y0 + h * 0.5);
    let spot = TOWER_SPOTS.iter().any(|&(la, lo, r)| {
        let (dn, de) = ((bla - la) * 110_540.0, (blo - lo) * 111_320.0 * la.to_radians().cos());
        dn * dn + de * de < r * r
    });
    // (round a spot, within 800 m, its own group is the only one: one cluster to an island)
    let near_spot = !spot && TOWER_SPOTS.iter().any(|&(la, lo, _)| {
        let (dn, de) = ((bla - la) * 110_540.0, (blo - lo) * 111_320.0 * la.to_radians().cos());
        dn * dn + de * de < 800.0 * 800.0
    });
    let cluster = spot || (!near_spot && bu(i.div_euclid(3), j.div_euclid(3), 8200) < 0.6);
    let water_tower = z == 2
        && bu(i, j, 8100) < if spot { 0.6 } else if cluster { 0.28 } else { 0.04 }
        && near_water(k, terrain, x0 + w * 0.5, y0 + h * 0.5, w.max(h) * 0.5 + 70.0);
    let tower_cls: &[Class] = &[Class::Tower];
    if need > 0.0 && tallest(if water_tower { tower_cls } else { classes }) < need && tallest(classes) < need {
        return out;
    }
    let dens = density(k, x0 + w * 0.5, y0 + h * 0.5);
    let built_at = |x: f64, y: f64| {
        let (la, lo) = to_lat_lon(k, x, y);
        built_share(terrain, la, lo, 40.0)
    };
    if z == 0 {
        // houses: two rows facing their streets
        let n = (w / HOUSE_LOT).floor().max(1.0) as usize;
        let depth = h * 0.5;
        for row in 0..2 {
            for l in 0..n {
                let lot = (row * n + l) as u32;
                let (ls, lw) = house_lot(i, j, row, l, n, w);
                let drive_right = bu(i, j, 30 + lot) < 0.5;
                // the archetypes that fit: along the street at most the lot less the driveway,
                // at most 16 m deep
                let mut fits: Vec<(usize, u32)> = Vec::new();
                for (a, r) in archs.iter().enumerate() {
                    if r.class != Class::House {
                        continue;
                    }
                    let (ax, az) = (r.size[0] as f64, r.size[1] as f64);
                    if ax <= lw - 6.0 && az <= 16.0 {
                        fits.push((a, 0));
                    }
                    if az <= lw - 6.0 && ax <= 16.0 {
                        fits.push((a, 1));
                    }
                }
                if fits.is_empty() {
                    continue;
                }
                // the lot's house, or where it does not fit (a back corner over the water on a
                // narrow island, a road), a smaller one, and nearer the street
                let first = (bh(i, j, 10 + lot) as usize) % fits.len();
                let mut order: Vec<(usize, u32)> = vec![fits[first]];
                let mut rest: Vec<(usize, u32)> = fits.iter().copied().filter(|f| *f != fits[first]).collect();
                rest.sort_by(|x, y| {
                    let d = |f: &(usize, u32)| if f.1 == 0 { archs[f.0].size[1] } else { archs[f.0].size[0] };
                    d(x).total_cmp(&d(y))
                });
                order.extend(rest.into_iter().take(2));
                let mut found = None;
                'try_house: for &(a, q) in &order {
                    let r = &archs[a];
                    if r.height < need {
                        continue;
                    }
                    let quarter = q + if bu(i, j, 20 + lot) < 0.5 { 2 } else { 0 };
                    let (ax, az) = if quarter % 2 == 0 { (r.size[0] as f64, r.size[1] as f64) } else { (r.size[1] as f64, r.size[0] as f64) };
                    // (built up to a fifth larger where the lot has room: the house fills its lot
                    // as Miami's do, not a small box on a lawn)
                    let scale = (1.02 + 0.18 * bu(i, j, 40 + lot)).min((lw - 6.0) / ax).min(16.0 / az).max(0.94);
                    let (hx, hy) = (ax * 0.5 * scale, az * 0.5 * scale);
                    // along the street: centred in what the driveway leaves; back from the street
                    let u = if drive_right { 1.5 + (lw - 6.0) * 0.5 } else { 4.5 + (lw - 6.0) * 0.5 };
                    for front in [front_yard(i, j, lot), 3.0] {
                        let v = front + hy + 0.5;
                        let px = x0 + ls + u;
                        let py = if row == 0 { y0 + v } else { y0 + h - v };
                        // (mapped water raised above the sea is the islands' land: built enough)
                        if built_at(px, py) < 0.15 && (buildable(k, terrain, px, py) || !house_ground(k, terrain, px, py)) {
                            continue;
                        }
                        let (ex, ey) = (hx + 1.0, hy + 1.0);
                        let ok = |x: f64, y: f64| house_ground(k, terrain, x, y);
                        if !(ok(px, py) && ok(px - ex, py - ey) && ok(px + ex, py + ey) && ok(px + ex, py - ey) && ok(px - ex, py + ey)) {
                            continue;
                        }
                        let (wx, wy) = to_world(px, py);
                        if on_way(wx, wy, hx.max(hy) + 3.0) {
                            continue;
                        }
                        found = Some((a, px, py, quarter, scale, hx, hy));
                        break 'try_house;
                    }
                }
                let _ = depth;
                let Some((a, px, py, quarter, scale, hx, hy)) = found else { continue };
                out.push(Placed { arch: a, x: px, y: py, quarter, scale, hx, hy });
                // its pool, patio and lanai against the back of the house (four houses in five),
                // set to one side of it or the other, only with the house
                if bu(i, j, 600 + lot) < 0.8 {
                    let pools: Vec<usize> = archs.iter().enumerate().filter(|(_, r)| r.class == Class::Pool).map(|(a, _)| a).collect();
                    if !pools.is_empty() {
                        let pa = pools[(bh(i, j, 610 + lot) as usize) % pools.len()];
                        // (the patio's house edge on the house's back wall)
                        let qy = if row == 0 { py + hy + 7.0 } else { py - hy - 7.0 };
                        let lo = x0 + ls + 5.7;
                        let hi = (x0 + ls + lw - 5.7).max(lo);
                        let qx = (px + (hx - 5.5).max(0.0) * (bu(i, j, 620 + lot) * 2.0 - 1.0)).clamp(lo, hi);
                        let far = if row == 0 { qy + 7.0 - y0 } else { y0 + h - (qy - 7.0) };
                        let pool_ok = far < h * 0.5 - 0.5 && buildable(k, terrain, qx, qy) && buildable(k, terrain, qx, qy + if row == 0 { 7.0 } else { -7.0 });
                        if pool_ok && archs[pa].height >= need {
                            out.push(Placed { arch: pa, x: qx, y: qy, quarter: if row == 0 { 2 } else { 0 }, scale: 1.0, hx: 5.5, hy: 7.0 });
                        }
                    }
                }
                // a hedge along the lot's line on its left, from behind the front yard to the
                // back line (two lot lines in three), in 8 m pieces with a gap now and then
                if l > 0 && bu(i, j, 640 + lot) < 0.67 {
                    if let Some(ha) = archs.iter().position(|r| r.class == Class::Hedge) {
                        if archs[ha].height >= need {
                            let hxl = x0 + ls;
                            let mut v = front_yard(i, j, lot) + 4.0;
                            let mut p = 0u32;
                            while v + 4.0 < h * 0.5 - 0.5 {
                                let hyl = if row == 0 { y0 + v + 4.0 } else { y0 + h - v - 4.0 };
                                if bu(i, j, 660 + lot * 16 + p) < 0.85 && buildable(k, terrain, hxl, hyl) {
                                    out.push(Placed { arch: ha, x: hxl, y: hyl, quarter: 0, scale: 1.0, hx: 0.5, hy: 4.1 });
                                }
                                v += 8.2;
                                p += 1;
                            }
                        }
                    }
                }
            }
        }
        return out;
    }
    let (nx, ny) = match z {
        3 => {
            if bu(i, j, 2) < 0.35 {
                (1, 1)
            } else {
                (2, 1)
            }
        }
        // (the mid-rise and walk-up blocks vary: a whole-block slab or court now and then, a
        // few big lots, or many small ones; never the same grain block after block)
        2 if density_at_block(k, i, j) > 0.22 => {
            let u = bu(i, j, 7);
            if u < 0.25 {
                (1, 1)
            } else if u < 0.55 {
                (2, 1)
            } else {
                (2, 2)
            }
        }
        2 => {
            let u = bu(i, j, 7);
            if u < 0.05 {
                (1, 1)
            } else if u < 0.14 {
                (2, 1)
            } else if u < 0.36 {
                (2, 2)
            } else {
                (3, 2)
            }
        }
        _ => {
            let u = bu(i, j, 7);
            if u < 0.05 {
                (1, 1)
            } else if u < 0.3 {
                (2, 2)
            } else if u < 0.6 {
                (3, 2)
            } else {
                (4, 3)
            }
        }
    };
    // (one or two big lots only away from the water: by it the drive and the banks take a
    // bite out of a big building's lot, and the block would stand empty)
    let (nx, ny) = if z <= 2 && nx * ny <= 2 && near_water(k, terrain, x0 + w * 0.5, y0 + h * 0.5, w.max(h) * 0.5 + 40.0) { (3, 2) } else { (nx, ny) };
    // (a waterfront tower's block: four lots, the tower on one with its podium inside it)
    let (nx, ny) = if water_tower { (2, 2) } else { (nx, ny) };
    let (lw, lh) = (w / nx as f64, h / ny as f64);
    // (a tower block's tower stands on the lot farthest from the water: fewest water samples
    // round its centre at 30 and 60 m)
    let tower_lot: u32 = if water_tower {
        (0..nx * ny)
            .min_by_key(|&lot| {
                let (lx, ly) = (lot % nx, lot / nx);
                let (cx, cy) = (x0 + (lx as f64 + 0.5) * lw, y0 + (ly as f64 + 0.5) * lh);
                (0..16)
                    .flat_map(|n| [30.0, 60.0].map(|r| (n, r)))
                    .filter(|&(n, r)| {
                        let a = n as f64 * std::f64::consts::TAU / 16.0;
                        water_at(k, terrain, cx + r * a.cos(), cy + r * a.sin())
                    })
                    .count()
            })
            .unwrap_or(0) as u32
    } else {
        0
    };
    // (each model at most once in a block where another fits: no row of identical buildings)
    let mut used: Vec<usize> = Vec::new();
    for ly in 0..ny {
        for lx in 0..nx {
            let lot = (ly * nx + lx) as u32;
            // (the tower block's other lots are mid-rises: no second, squat tower beside it)
            let class = if water_tower && lot == tower_lot {
                Class::Tower
            } else if water_tower {
                Class::MidRise
            } else {
                classes[(bh(i, j, 10 + lot) as usize) % classes.len()]
            };
            let (cx, cy) = (x0 + (lx as f64 + 0.5) * lw, y0 + (ly as f64 + 0.5) * lh);
            let mut fits: Vec<(usize, u32)> = Vec::new();
            for (a, r) in archs.iter().enumerate() {
                if r.class != class {
                    continue;
                }
                // (no supertowers: the skyline is a band of towers of 25-60 storeys)
                if class == Class::Tower && r.height > 255.0 {
                    continue;
                }
                // (the waterfront's towers are residential: white balcony bands over a podium,
                // where one fits)
                if water_tower && lot == tower_lot && !r.slim {
                    continue;
                }
                // (outside the downtown cores a tower is an apartment tower, white banded, where
                // one fits: the glass office towers stand downtown)
                if class == Class::Tower && z < 3 && !r.residential && archs.iter().any(|o| o.class == Class::Tower && o.residential && o.size[0] as f64 <= lw - 4.0 && o.size[1] as f64 <= lh - 4.0) {
                    continue;
                }
                // (and its mid-rises apartments, condos and stucco blocks: an office block only
                // where nothing else fits)
                if r.office && z < 3 && archs.iter().any(|o| o.class == class && !o.office && o.size[0] as f64 <= lw - 4.0 && o.size[1] as f64 <= lh - 4.0) {
                    continue;
                }
                let (ax, az) = (r.size[0] as f64, r.size[1] as f64);
                if ax <= lw - 4.0 && az <= lh - 4.0 {
                    fits.push((a, 0));
                }
                if az <= lw - 4.0 && ax <= lh - 4.0 {
                    fits.push((a, 1));
                }
            }
            if fits.is_empty() {
                continue;
            }
            // a landmark tower now and then on the first lot of a block in the heart of a core
            let landmark = class == Class::Tower && z == 3 && lot == 0 && dens > 0.8 && bu(i, j, 97) < 0.22;
            let marks: Vec<(usize, u32)> = if landmark {
                archs
                    .iter()
                    .enumerate()
                    .filter(|(_, r)| r.class == Class::Landmark && r.height <= 255.0 && r.size[0] as f64 <= lw - 4.0 && r.size[1] as f64 <= lh - 4.0)
                    .map(|(a, _)| (a, 0))
                    .collect()
            } else {
                Vec::new()
            };
            let pick = if !marks.is_empty() {
                marks[(bh(i, j, 98) as usize) % marks.len()]
            } else if class == Class::Tower {
                // taller towers nearer the core centres, and now and then a much taller one
                // (outside the cores only the shortest towers: the mid-rise city round them is
                // 10-25 storeys)
                let mut want = if z == 3 {
                    70.0 + 170.0 * dens.powf(1.3) * (0.55 + 0.6 * bu(i, j, 90 + lot))
                } else if water_tower && spot {
                    // (a spot's group is the tall one: 30-45 storeys, seen across the bay)
                    100.0 + 50.0 * bu(i, j, 90 + lot)
                } else if water_tower {
                    // (15 to 45 storeys, most of them mid-height)
                    50.0 + 100.0 * bu(i, j, 90 + lot).powf(1.3)
                } else {
                    55.0 + 35.0 * bu(i, j, 90 + lot)
                };
                if z == 3 && bu(i, j, 95 + lot) < 0.15 {
                    want *= 1.6;
                }
                let mut best = fits[0];
                let mut bd = f64::MAX;
                for (n, &(a, q)) in fits.iter().enumerate() {
                    let d = (archs[a].height as f64 - want).abs() + bu(i, j, 200 + lot * 97 + n as u32) * 35.0;
                    if d < bd {
                        bd = d;
                        best = (a, q);
                    }
                }
                best
            } else {
                // a building that fills its lot (a big lot is one big building, not a small
                // one lost in it), any of them where none does
                let room = (lw - 4.0) * (lh - 4.0);
                let fresh: Vec<(usize, u32)> = fits.iter().copied().filter(|f| !used.contains(&f.0)).collect();
                let fits = if fresh.is_empty() { fits.clone() } else { fresh };
                // (each district of 3 x 3 blocks builds from its own third of the models: no one
                // model all over the city, and a district its own character)
                let (di, dj) = (i.div_euclid(3), j.div_euclid(3));
                let local: Vec<(usize, u32)> = fits.iter().copied().filter(|&(a, _)| bh(di, dj, 9900 + a as u32) % 3 == 0).collect();
                let fits = if local.is_empty() { fits } else { local };
                let big: Vec<(usize, u32)> = fits.iter().copied().filter(|&(a, _)| (archs[a].size[0] * archs[a].size[1]) as f64 >= 0.4 * room).collect();
                let from = if big.is_empty() { &fits } else { &big };
                // (two lots in three take one of the shaped blocks where one fits: the boxes
                // are the minority)
                let shaped: Vec<(usize, u32)> = fits.iter().copied().filter(|&(a, _)| archs[a].shaped).collect();
                let from = if !shaped.is_empty() && bu(i, j, 7800 + lot) < 0.5 { &shaped } else { from };
                from[(bh(i, j, 12 + lot) as usize) % from.len()]
            };
            let r = &archs[pick.0];
            if r.height < need {
                continue;
            }
            let quarter = pick.1 + if bu(i, j, 20 + lot) < 0.5 { 2 } else { 0 };
            let (hx, hy) = if quarter % 2 == 0 { (r.size[0] as f64 * 0.5, r.size[1] as f64 * 0.5) } else { (r.size[1] as f64 * 0.5, r.size[0] as f64 * 0.5) };
            // (a building with room to spare in its lot is built a little larger, up to a fifth:
            // the lot filled, not a small block in a lawn; towers keep their size)
            let room = if class == Class::Tower { 1.0 } else { ((lw - 4.0) / (2.0 * hx)).min((lh - 4.0) / (2.0 * hy)) * 0.97 };
            let scale = (0.93 + 0.1 * bu(i, j, 40 + lot)) * room.clamp(1.0, 1.2);
            // slack in the lot: set back from the street by a random amount
            let sx = (lw * 0.5 - 2.0 - hx * scale).max(0.0);
            let sy = (lh * 0.5 - 2.0 - hy * scale).max(0.0);
            let (mut px, mut py) = (cx + (bu(i, j, 60 + lot) * 2.0 - 1.0) * sx * 0.7, cy + (bu(i, j, 80 + lot) * 2.0 - 1.0) * sy * 0.7);
            // downtown a tower stands at one end of its lot, a podium (garage or shops) fills
            // the rest, as the parking podiums of real towers do
            let podium = class == Class::Tower && z == 3 && sy > 14.0;
            let side = if bu(i, j, 85 + lot) < 0.5 { 1.0 } else { -1.0 };
            if podium {
                py = cy + side * sy;
                px = cx + (bu(i, j, 60 + lot) * 2.0 - 1.0) * sx * 0.3;
            }
            // (the waterfront park runs along the water within WATERFRONT m: nothing built on it)
            if z >= 2 && near_water(k, terrain, px, py, hx.max(hy) * scale + WATERFRONT) {
                continue;
            }
            // (a tower stands well back on land: water anywhere within its reach, finer sampled)
            if class == Class::Tower && (0..24).any(|n| {
                let a = n as f64 * std::f64::consts::TAU / 24.0;
                [0.5, 1.0].iter().any(|f| {
                    let r = (hx.max(hy) * scale + WATERFRONT) * f;
                    water_at(k, terrain, px + r * a.cos(), py + r * a.sin())
                })
            }) {
                continue;
            }
            if built_at(px, py) < if class == Class::Tower { 0.15 } else { 0.3 } {
                continue;
            }
            let (ex, ey) = (hx * scale + 1.0, hy * scale + 1.0);
            if !(buildable(k, terrain, px, py) && buildable(k, terrain, px - ex, py - ey) && buildable(k, terrain, px + ex, py - ey) && buildable(k, terrain, px + ex, py + ey) && buildable(k, terrain, px - ex, py + ey)) {
                continue;
            }
            if podium {
                // the free span: from the lot's far edge to the tower, less a gap
                let free = 2.0 * sy - 1.5;
                let gy = py - side * (hy * scale + 1.5 + free * 0.5);
                let mut best: Option<(usize, u32, f64)> = None;
                for (a, r) in archs.iter().enumerate() {
                    if r.class != Class::LowRise {
                        continue;
                    }
                    for q in 0..2u32 {
                        let (ax, ay) = if q == 0 { (r.size[0] as f64, r.size[1] as f64) } else { (r.size[1] as f64, r.size[0] as f64) };
                        if ax <= lw - 4.0 && ay <= free && best.is_none_or(|b| ax * ay > b.2) {
                            best = Some((a, q, ax * ay));
                        }
                    }
                }
                if let Some((a, q, _)) = best {
                    let r = &archs[a];
                    let (ax, ay) = if q == 0 { (r.size[0] as f64, r.size[1] as f64) } else { (r.size[1] as f64, r.size[0] as f64) };
                    if r.height >= need && buildable(k, terrain, px, gy) && buildable(k, terrain, px, gy - side * ay * 0.5) {
                        out.push(Placed { arch: a, x: px, y: gy, quarter: q, scale: 1.0, hx: ax * 0.5, hy: ay * 0.5 });
                    }
                }
            }
            let (wx, wy) = to_world(px, py);
            if on_way(wx, wy, hx.max(hy) * scale + 3.0) {
                continue;
            }
            out.push(Placed { arch: pick.0, x: px, y: py, quarter, scale, hx: hx * scale, hy: hy * scale });
            used.push(pick.0);
        }
    }
    out
}

/// Is lat / lon in a city? (A cheap test before `Blocks::blocked`.)
pub fn in_city(lat: f64, lon: f64) -> bool {
    city_at_world(lat, lon).is_some()
}

/// The buildings' footprints of the blocks asked about so far (one tile's trees ask about the
/// same few blocks thousands of times).
#[derive(Default)]
pub struct Blocks {
    cache: std::collections::HashMap<(usize, i64, i64), Vec<[f64; 4]>>,
}

impl Blocks {
    /// Is lat / lon in a city's roadway, or under a building? (Trees keep out of both.)
    pub fn blocked(&mut self, lat: f64, lon: f64, archs: &[ArchRef], terrain: &Terrain) -> bool {
        let _t = Timer(3, std::time::Instant::now());
        let Some((k, x, y)) = city_at(lat, lon) else { return false };
        if archs.is_empty() {
            return false;
        }
        let (wx, wy) = to_world(x, y);
        if on_way(wx, wy, 0.0) {
            return true;
        }
        let (i, j) = cell(x, y);
        let (fx, fy) = (x - line_x(i), y - line_y(j));
        let (bxw, byw) = (line_x(i + 1) - line_x(i), line_y(j + 1) - line_y(j));
        // the roadways (the sidewalks may have trees)
        let road = |a: bool| half_width(a) - sidewalk(a);
        if fx < road(art_x(i)) || fx > bxw - road(art_x(i + 1)) || fy < road(art_y(j)) || fy > byw - road(art_y(j + 1)) {
            return true;
        }
        let b = self.cache.entry((k, i, j)).or_insert_with(|| block(k, archs, terrain, i, j, 0.0).iter().map(|p| [p.x, p.y, p.hx, p.hy]).collect());
        b.iter().any(|p| (x - p[0]).abs() < p[2] + 1.5 && (y - p[1]).abs() < p[3] + 1.5)
    }
}

/// Height (m) a building must reach to be kept in a tree tile `k` levels coarser than the finest
/// (the far tiles: small buildings are below a pixel there).
fn min_height(k: u8) -> f32 {
    match k {
        0 => 0.0,
        1 => 14.0,
        2 => 30.0,
        3 => 60.0,
        _ => 110.0,
    }
}

/// Is the plane point's foot in tree tile `id`?
fn in_tile(k: usize, x: f64, y: f64, id: TileId) -> Option<DVec3> {
    // (a cheap test first: outside the tile's box in the plan, 2 m round)
    let (bl, bh_, cl, ch) = TILE_BOX.with(|b| b.get());
    if x < bl - 2.0 || x > bh_ + 2.0 || y < cl - 2.0 || y > ch + 2.0 {
        return None;
    }
    let (lat, lon) = to_lat_lon(k, x, y);
    if city_at_world(lat, lon).map(|v| v.0) != Some(k) {
        return None;
    }
    let d = super::tiles::dir_from_lat_lon(lat, lon);
    let (face, u, v) = super::forest::dir_to_face_uv(d);
    let cells = 1u64 << id.level;
    let to_cell = |c: f64| (((c + 1.0) * 0.5 * cells as f64).floor() as i64).clamp(0, cells as i64 - 1) as u32;
    (face == id.face && to_cell(u) == id.x && to_cell(v) == id.y).then_some(d)
}

/// The buildings whose centres lie in tree tile `id`, as plant records into `tile`; on the
/// finest tiles also the palms along the sidewalks.
pub fn grow(id: TileId, terrain: &Terrain, sp: &Species, tile: &mut TreeTile) {
    let _t = Timer(0, std::time::Instant::now());
    let (archs, infos) = (&sp.buildings[..], &sp.infos[..]);
    if archs.is_empty() {
        return;
    }
    let (u0, v0, s) = id.uv();
    let corners: Vec<DVec3> = [(0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0), (0.5, 0.5)].iter().map(|(a, b)| face_dir(id.face, u0 + a * s, v0 + b * s)).collect();
    for (k, c) in CITIES.iter().enumerate() {
        // the tile's box in the city plane
        let world: Vec<(f64, f64)> = corners.iter().map(|d| plane(k, *d)).collect();
        let (wxl, wxh) = world.iter().fold((f64::MAX, f64::MIN), |a, p| (a.0.min(p.0), a.1.max(p.0)));
        let (wyl, wyh) = world.iter().fold((f64::MAX, f64::MIN), |a, p| (a.0.min(p.1), a.1.max(p.1)));
        if !(wxh < -c.radius || wxl > c.radius || wyh < -c.radius || wyl > c.radius) {
            way_items(k, terrain, sp, id, tile, TREE_LEVEL.saturating_sub(id.level), (wxl, wyl), (wxh, wyh));
        }
        let pts: Vec<(f64, f64)> = world.iter().map(|p| to_plan(p.0, p.1)).collect();
        let (xl, xh) = pts.iter().fold((f64::MAX, f64::MIN), |a, p| (a.0.min(p.0), a.1.max(p.0)));
        let (yl, yh) = pts.iter().fold((f64::MAX, f64::MIN), |a, p| (a.0.min(p.1), a.1.max(p.1)));
        if xh < -c.radius || xl > c.radius || yh < -c.radius || yl > c.radius {
            continue;
        }
        TILE_BOX.with(|b| b.set((xl, xh, yl, yh)));
        let (xl, xh, yl, yh) = (xl.max(-c.radius), xh.min(c.radius), yl.max(-c.radius), yh.min(c.radius));
        let lvl = TREE_LEVEL.saturating_sub(id.level);
        let need = min_height(lvl);
        // (the blocks the tile overlaps, and 30 m round: the lines are moved by up to 12 m, and
        // a block's palms, docks and decks reach a little past it)
        let wet_tile = {
            let (la, lo) = lat_lon(id.center_dir());
            terrain.cover.fractions(la, lo, id.edge() * 1.5).map(|f| f[lc::WATER] > 0.0).unwrap_or(true)
        };
        for j in ((yl - 30.0) / BY).floor() as i64..=((yh + 30.0) / BY).floor() as i64 {
            for i in ((xl - 30.0) / BX).floor() as i64..=((xh + 30.0) / BX).floor() as i64 {
                let placed = block(k, archs, terrain, i, j, need);
                for p in &placed {
                    let Some(d) = in_tile(k, p.x, p.y, id) else { continue };
                    if tile.recs.len() >= MAX_PER_TILE {
                        break;
                    }
                    let (lat, lon) = lat_lon(d);
                    let r = &archs[p.arch];
                    let seed = 1 + (bh((p.x * 4.0) as i64, (p.y * 4.0) as i64, 7) % 8190);
                    // (sunk a little: the ground under a footprint is never quite flat; no
                    // thinning level: impostor.rint never thins buildings)
                    // (a pool and its patio lie flat on the ground, a few cm up: sunk as the
                    // buildings are, all 20 cm of it was under the lawn)
                    let sink = if r.class == Class::Pool { -0.03 } else if r.class == Class::Hedge { 0.1 } else { 0.4 };
                    let rows = frame_rows(d, tile.center, terrain.height(lat, lon).max(0.0) as f64 - sink, p.quarter as f64 * std::f64::consts::FRAC_PI_2, p.scale);
                    push_rec(tile, rows, super::forest::rec_data(r.variant, seed << 8), &infos[r.variant]);
                }
                // (the buildings first: a tile full of cars must not lose a tower)
                if lvl == 0 && !sp.palms.is_empty() {
                    street_palms(k, terrain, sp, i, j, id, tile);
                    lot_trees(k, terrain, sp, i, j, id, tile, &placed);
                }
                if lvl == 0 {
                    docks(k, terrain, sp, i, j, id, tile, &placed);
                    parked(k, terrain, sp, i, j, id, tile, &placed);
                }
                // (on the coarser tiles only the bridge decks: none where there is no water)
                if lvl == 0 || (lvl <= 2 && wet_tile) {
                    streets(k, terrain, sp, i, j, id, tile, lvl == 0);
                }
            }
        }
        // boats out on the water: one cell of BOAT_CELL m at a time, a boat in some
        if lvl <= 1 {
            for b in (yl / BOAT_CELL).floor() as i64..=(yh / BOAT_CELL).floor() as i64 {
                for a in (xl / BOAT_CELL).floor() as i64..=(xh / BOAT_CELL).floor() as i64 {
                    open_water_boat(k, terrain, sp, a, b, lvl, id, tile);
                }
            }
        }
    }
}


/// The car archetypes (compact, sedan, SUV, pickup, van, bus) and the bridge decks (arterial,
/// side street).
fn car_kinds(archs: &[ArchRef]) -> (Vec<&ArchRef>, Vec<&ArchRef>) {
    (archs.iter().filter(|a| a.class == Class::Car).collect(), archs.iter().filter(|a| a.class == Class::Bridge).collect())
}

thread_local! {
    /// `crossing`'s water test, per thread (the same points are asked for by every 20 m of a
    /// crossing and by every street of a tile)
    static WET: std::cell::RefCell<std::collections::HashMap<(usize, i64, i64), bool>> = Default::default();
    static CROSS: std::cell::RefCell<std::collections::HashMap<(usize, bool, i64, i64), Option<(f64, f64)>>> = Default::default();
    /// `crossing_at`'s banks: per line and 5 m grid point along it, and direction, the bank
    /// (its place along the line) the walk from there finds (true, every point of a crossing
    /// walks to the same two), or how far on it is known there is none (false)
    static BANK: std::cell::RefCell<std::collections::HashMap<(usize, bool, i64, i64, bool), (bool, f64)>> = Default::default();
}

/// Is the plan point on mapped water whose lower quartile of heights over ~200 m is the sea's?
fn wet_at(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    let (la, lo) = to_lat_lon(k, x, y);
    if terrain.cover.class_group(la, lo) != Some(lc::WATER) {
        return false;
    }
    let (dla, dlo) = (30.0 / 110_540.0, 30.0 / (111_320.0 * la.to_radians().cos()));
    let mut h: Vec<f32> = Vec::with_capacity(49);
    for a in -3..=3 {
        for b in -3..=3 {
            let (pa, po) = (la + a as f64 * dla, lo + b as f64 * dlo);
            if terrain.cover.class_group(pa, po) == Some(lc::WATER) {
                h.push(terrain.height(pa, po));
            }
        }
    }
    h.sort_by(|a, b| a.total_cmp(b));
    // (the lower seventh: a causeway's raised strip covers a good part of the window on its
    // own line, a pond all of it)
    h[h.len() / 7] < 0.6
}

/// Is the plan point on the land cover's water at all? (Things that stand on the ground keep
/// off it: the real causeways and bridges are raised ground in the 30 m data, drawn as water.)
fn mapped_water(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    // (within 5 m: the terrain's shore lies anywhere in the land cover's edge pixels)
    [(0.0, 0.0), (5.0, 0.0), (-5.0, 0.0), (0.0, 5.0), (0.0, -5.0)].iter().any(|(dx, dy)| {
        let (la, lo) = to_lat_lon(k, x + dx, y + dy);
        terrain.cover.class_group(la, lo) == Some(lc::WATER)
    })
}

/// The bridge, if the street through (x, y) crosses water here: how far back and on to its banks. Short crossings (canals, the
/// river: land within 160 m both ways along the street) always; long ones (across the bay, to
/// 1.6 km) only on every other arterial, as causeways.
fn crossing(k: usize, terrain: &Terrain, x: f64, y: f64, along_x: bool, arterial: bool, line: i64) -> Option<(f64, f64)> {
    // (kept per thread, by the point quantised to 2 m)
    let along = if along_x { x } else { y };
    let key = (k, along_x, line, (along * 0.5).round() as i64);
    if let Some(v) = CROSS.with(|c| c.borrow().get(&key).copied()) {
        return v;
    }
    let v = crossing_at(k, terrain, x, y, along_x, arterial, line);
    CROSS.with(|c| {
        let mut c = c.borrow_mut();
        if c.len() > 1 << 20 {
            c.clear();
        }
        c.insert(key, v);
    });
    v
}

fn crossing_at(k: usize, terrain: &Terrain, x: f64, y: f64, along_x: bool, arterial: bool, line: i64) -> Option<(f64, f64)> {
    // (crossings are decided on the land cover's water alone: the 30 m data is a surface
    // model, the real bridges and causeways are in it as raised ground, which would cut ours in
    // two)
    // ponds above sea level are not crossed: the lower quartile of the water's heights over
    // ~200 m round about must be the sea's (a causeway is a thin line in that window)
    let wet = |x: f64, y: f64| {
        let key = (k, (x * 0.2).round() as i64, (y * 0.2).round() as i64);
        if let Some(v) = WET.with(|c| c.borrow().get(&key).copied()) {
            return v;
        }
        let v = {
            let (la, lo) = to_lat_lon(k, x, y);
            terrain.cover.class_group(la, lo) == Some(lc::WATER)
        };
        WET.with(|c| {
            let mut c = c.borrow_mut();
            if c.len() > 1 << 21 {
                c.clear();
            }
            c.insert(key, v);
        });
        v
    };
    if !wet(x, y) {
        return None;
    }
    // decided for the whole crossing, the same at every point of it: walk out both ways to the
    // first bank (60 m of solid land), within reach (canals for the side streets, rivers for
    // the arterials, the bay only on the causeways); then the crossing must have water both
    // sides of the street at its middle (a street running along a shore just off it does not)
    let reach = if arterial && bh(line, along_x as i64, 77) % 2 == 0 { 6000.0 } else if arterial { 250.0 } else { 70.0 };
    let pt = |s: f64| if along_x { (x + s, y) } else { (x, y + s) };
    // (the walk steps on a 5 m grid fixed along the line, so every point of one crossing finds
    // the same two banks: the whole bridge is laid from them, streets)
    let g0 = if along_x { x } else { y };
    let bank = |dir: f64| -> Option<f64> {
        let first = if dir > 0.0 { (g0 / 5.0).ceil() * 5.0 } else { (g0 / 5.0).floor() * 5.0 };
        let mut s = (first - g0).abs();
        // (memoised: the grid points walked over, and where they lead)
        let key = |s: f64| (k, along_x, line, ((g0 + dir * s) / 5.0).round() as i64, dir > 0.0);
        let mut seen: Vec<(usize, bool, i64, i64, bool)> = Vec::new();
        let keep = |seen: &[(usize, bool, i64, i64, bool)], v: (bool, f64)| {
            BANK.with(|c| {
                let mut c = c.borrow_mut();
                if c.len() > 1 << 21 {
                    c.clear();
                }
                for kk in seen {
                    c.insert(*kk, v);
                }
            });
        };
        // (each way as far as the whole crossing may be long: then every point of it finds
        // the same banks, wherever it stands)
        while s <= 2.0 * reach {
            match BANK.with(|c| c.borrow().get(&key(s)).copied()) {
                Some((true, g)) => {
                    keep(&seen, (true, g));
                    return Some((g - g0).abs());
                }
                Some((false, g)) => {
                    // (no bank before g: on from there)
                    let to = (g - g0).abs();
                    if to > s {
                        s = to;
                        continue;
                    }
                }
                None => {}
            }
            seen.push(key(s));
            // (60 m of land, 250 m on the causeways: a thinner strip, the real causeway's road
            // and verges in the land cover, is bridged over: the terrain draws it as water)
            let need = if reach > 1000.0 { 26 } else { 7 };
            let solid = (0..need).all(|n| {
                let (px, py) = pt(dir * (s + 10.0 * n as f64));
                !wet(px, py)
            });
            if solid {
                keep(&seen, (true, g0 + dir * s));
                return Some(s);
            }
            s += 5.0;
        }
        // (none within reach: the points passed know there is none before here)
        keep(&seen, (false, g0 + dir * s));
        None
    };
    let (Some(a), Some(b)) = (bank(-1.0), bank(1.0)) else { return None };
    if a + b > 2.0 * reach {
        return None;
    }
    // (a side street bridges a canal, not a river: it ends at the river's bank, and only the
    // arterials and every third street line cross it, every 300-400 m, as real cities bridge
    // their rivers and wider canals)
    if !arterial && a + b > 60.0 && line.rem_euclid(3) != 0 {
        return None;
    }
    // (the water is followed by the land cover alone, point by point (busy shores, boats and
    // marinas raise the surface model there); whether it is the sea or a pond above it, which
    // the terrain draws as land in a city, is asked once, at the crossing's middle)
    {
        let (mx, my) = pt((b - a) * 0.5);
        if !wet_at(k, terrain, mx, my) {
            return None;
        }
    }
    // (a crossing shorter than a deck and a half is a sliver of the land cover's edge, not a
    // canal: a lone slab)
    if a + b < 25.0 {
        return None;
    }
    // (both banks must be ground the terrain draws: where the land cover's land is under the
    // sea in the elevation data, a causeway's line or a mudflat, the terrain draws water, and a
    // bridge landing there would end in the bay)
    let landed = |s0: f64, dir: f64| {
        [5.0, 15.0, 25.0]
            .iter()
            .filter(|&&d| {
                let (px, py) = pt(s0 + dir * d);
                let (la, lo) = to_lat_lon(k, px, py);
                terrain.height(la, lo) > 0.3
            })
            .count()
            >= 2
    };
    if !landed(-a, -1.0) || !landed(b, 1.0) {
        return None;
    }
    let (mx, my) = pt((b - a) * 0.5);
    // (a street that runs along a river or canal, not across it, has no bridge down its length)
    {
        let (w0, w1) = (to_world(pt((b - a) * 0.5 - 10.0).0, pt((b - a) * 0.5 - 10.0).1), to_world(pt((b - a) * 0.5 + 10.0).0, pt((b - a) * 0.5 + 10.0).1));
        let (wm, (sx, sy)) = (to_world(mx, my), (w1.0 - w0.0, w1.1 - w0.1));
        if let Some((cx, cy)) = channel_dir(wm.0, wm.1) {
            let l = (sx * sx + sy * sy).sqrt().max(1e-6);
            if ((sx * cx + sy * cy) / l).abs() > 0.6 {
                return None;
            }
        }
    }
    let (px, py) = if along_x { (0.0, 40.0) } else { (40.0, 0.0) };
    (wet(mx + px, my + py) && wet(mx - px, my - py)).then_some((a, b))
}

/// A crossing's arch at a point (a back to its bank, b on to the other): the deck's height
/// over the water level and its slope along the street.
fn arch(a: f64, b: f64) -> (f64, f64) {
    let span = (a + b).max(1.0);
    let rise = (span * 0.035).min(7.0);
    let f = a / span;
    (rise * (std::f64::consts::PI * f).sin(), rise * std::f64::consts::PI / span * (std::f64::consts::PI * f).cos())
}

/// Bridge decks and traffic on the street lines of block (i, j) (as street_palms: the
/// north-south street at x = i BX along this block's y span, the east-west one at y = j BY
/// along its x span, crossings included). `cars`: also the traffic (finest tiles only).
#[allow(clippy::too_many_arguments)]
fn streets(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile, cars: bool) {
    let _t = Timer(1, std::time::Instant::now());
    let (kinds, decks) = car_kinds(&sp.buildings);
    if decks.len() < 2 {
        return;
    }
    for along_x in [false, true] {
        let (line, a) = if along_x { (j, art_y(j)) } else { (i, art_x(i)) };
        let (start, len) = if along_x { (line_x(i), line_x(i + 1) - line_x(i)) } else { (line_y(j), line_y(j + 1) - line_y(j)) };
        let fixed = if along_x { line_y(j) } else { line_x(i) };
        // (a street that does not pass the tile has nothing for it)
        {
            let (bl, bh_, cl, ch) = TILE_BOX.with(|b| b.get());
            let (lo, hi, flo, fhi) = if along_x { (bl, bh_, cl, ch) } else { (cl, ch, bl, bh_) };
            if fixed < flo - 20.0 || fixed > fhi + 20.0 || start + len < lo - 20.0 || start > hi + 20.0 {
                continue;
            }
        }
        let at = |s: f64, off: f64| if along_x { (start + s, fixed + off) } else { (fixed + off, start + s) };
        let yaw0 = if along_x { 0.0 } else { std::f64::consts::FRAC_PI_2 };
        // the bridges: each crossing found along this stretch of the street (a little past its
        // ends too: a bridge's abutment may reach into it), laid whole from bank to bank and
        // 10 m on to the land each side, in even pieces (21 m long, at most 20 m apart); this
        // block lays the pieces whose middles are on its stretch, its neighbour the rest. The
        // crossing is decided at its own middle, the same for every block it passes
        let mut spans: Vec<(f64, f64)> = Vec::new();
        let mut s = -30.0;
        while s < len + 30.0 {
            let (x, y) = at(s, 0.0);
            if let Some((ca, cb)) = crossing(k, terrain, x, y, along_x, a, line) {
                let (lo, hi) = (s - ca, s + cb);
                if !spans.iter().any(|&(l, _)| (l - lo).abs() < 1.0) {
                    let mid = (lo + hi) * 0.5;
                    let (mx, my) = at(mid, 0.0);
                    let same = crossing(k, terrain, mx, my, along_x, a, line).is_some_and(|(ma, mb)| ((mid - ma) - lo).abs() < 1.0 && ((mid + mb) - hi).abs() < 1.0);
                    if same {
                        spans.push((lo, hi));
                    }
                }
                s = s.max(hi);
            }
            s += 10.0;
        }
        // (heading from the street's own tangent in the city's plane, so the pieces follow its
        // curve end to end)
        let tang = |s: f64| {
            let (p0, p1) = (at(s - 2.0, 0.0), at(s + 2.0, 0.0));
            let (a0, a1) = (to_world(p0.0, p0.1), to_world(p1.0, p1.1));
            (a1.1 - a0.1).atan2(a1.0 - a0.0)
        };
        for (lo, hi) in spans {
            let (l0, l1) = (lo - 10.0, hi + 10.0);
            // (the deck's top meets the street at its ends: on the higher of the two banks'
            // ground, its arch over the water from there)
            let base = {
                let (ax, ay) = at(lo - 8.0, 0.0);
                let (bx, by) = at(hi + 8.0, 0.0);
                ground(k, terrain, ax, ay).max(ground(k, terrain, bx, by)) - 2.92 + 0.1
            };
            let n = ((l1 - l0) / 20.0).ceil().max(1.0) as u32;
            let step = (l1 - l0) / n as f64;
            for m in 0..n {
                let c = l0 + (m as f64 + 0.5) * step;
                if !(0.0..len).contains(&c) {
                    continue;
                }
                // (the arch over the water, level with it past the banks: the deck's ends run
                // into the rising ground)
                let (h, dh) = arch((c - lo).clamp(0.0, hi - lo), (hi - c).clamp(0.0, hi - lo));
                let (x, y) = at(c, 0.0);
                let (wx, wy) = to_world(x, y);
                let seed = bh(line, (start + c).round() as i64, 6000 + along_x as u32 * 50);
                put_world(k, sp, decks[if a { 0 } else { 1 }], wx, wy, base + h, tang(c), dh.atan(), seed, id, tile);
            }
        }
        // street lights along both sidewalks, every ~30 m on alternate sides, and traffic
        // signals at the street's crossings with arterials (on land only: bridges have lamps)
        if cars {
            let light = sp.buildings.iter().find(|r| r.class == Class::Street && r.height > 8.0);
            let signal = sp.buildings.iter().find(|r| r.class == Class::Street && r.height < 8.0);
            if let (Some(light), Some(signal)) = (light, signal) {
                let kerb = half_width(a) - sidewalk(a) + 0.6;
                let cross = |ii: i64, jj: i64| if along_x { half_width(art_x(ii)) } else { half_width(art_y(jj)) };
                let (c0, c1) = if along_x { (cross(i, j), len - cross(i + 1, j)) } else { (cross(i, j), len - cross(i, j + 1)) };
                let mut s = c0 + 6.0;
                let mut n = 0u32;
                while s < c1 - 4.0 {
                    let side = if n % 2 == 0 { -1.0 } else { 1.0 };
                    let (x, y) = at(s, side * kerb);
                    // (none on or under a bridge, its abutments included: the bridge has its own
                    // lamps on its parapets, and a street lamp there would stand in its lanes)
                    let bridged = [-14.0, 0.0, 14.0].iter().any(|d| {
                        let (cx, cy) = at(s + d, 0.0);
                        crossing(k, terrain, cx, cy, along_x, a, line).is_some()
                    });
                    if !bridged && !mapped_water(k, terrain, x, y) {
                        // (the arm reaches over the road: towards the line from this side)
                        let yaw = yaw0 - std::f64::consts::FRAC_PI_2 * side * if along_x { -1.0 } else { 1.0 };
                        put_at(k, sp, light, x, y, ground(k, terrain, x, y), yaw, bh(i, j, 8800 + n + along_x as u32 * 100), id, tile);
                    }
                    s += 30.0;
                    n += 1;
                }
                // the crossing at this block's start of the line, if either street is an arterial
                let other = if along_x { art_x(i) } else { art_y(j) };
                if (a || other) && !along_x {
                    let (lx, ly) = (line_x(i), line_y(j));
                    let (hx, hy) = (half_width(art_x(i)) - sidewalk(art_x(i)) + 0.7, half_width(art_y(j)) - sidewalk(art_y(j)) + 0.7);
                    for (cx, cy, yaw) in [(lx - hx, ly - hy, 0.0f64), (lx + hx, ly + hy, std::f64::consts::PI)] {
                        if !water_at(k, terrain, cx, cy) {
                            put_at(k, sp, signal, cx, cy, ground(k, terrain, cx, cy), yaw, bh(i, j, 8990), id, tile);
                        }
                    }
                }
            }
        }
        if !cars || kinds.len() < 6 {
            continue;
        }
        // traffic, driving on the right: lanes at +-1.75 and +-5.25 m on an arterial, +-2 m on
        // a side street; none in the crossings
        let lanes: &[f64] = if a { &[-5.25, -1.75, 1.75, 5.25] } else { &[-2.0, 2.0] };
        let road_x = |ii: i64| half_width(art_x(ii)) + 2.0;
        let road_y = |jj: i64| half_width(art_y(jj)) + 2.0;
        let (c0, c1) = if along_x { (road_x(i), len - road_x(i + 1)) } else { (road_y(j), len - road_y(j + 1)) };
        for (li, &off) in lanes.iter().enumerate() {
            let mut s = c0 + bu(i, j, 6500 + li as u32 + along_x as u32 * 10) * 20.0;
            let mut n = 0u32;
            while s < c1 {
                let salt = 7000 + (li as u32) * 100 + n + along_x as u32 * 1000;
                let busy = if a { 0.75 } else { 0.3 };
                if bu(i, j, salt) < busy {
                    let (x, y) = at(s, off);
                    // northbound / eastbound on the right of the centre line
                    let forward = if along_x { off < 0.0 } else { off > 0.0 };
                    let yaw = yaw0 + if forward { 0.0 } else { std::f64::consts::PI };
                    let kind = if a && bu(i, j, salt + 500) < 0.04 { 5 } else { (bh(i, j, salt + 600) % 5) as usize };
                    let over = crossing(k, terrain, x, y, along_x, a, line);
                    if over.is_none() && !water_at(k, terrain, x, y) {
                        put_at(k, sp, kinds[kind], x, y, ground(k, terrain, x, y), yaw, bh(i, j, salt + 700), id, tile);
                    } else if let Some((ca, cb)) = over {
                        let (h, dh) = arch(ca, cb);
                        let pitch = if forward { dh.atan() } else { -dh.atan() };
                        let (wx, wy) = to_world(x, y);
                        let (p0, p1) = (at(s - 2.0, off), at(s + 2.0, off));
                        let (a0, a1) = (to_world(p0.0, p0.1), to_world(p1.0, p1.1));
                        let tyaw = (a1.1 - a0.1).atan2(a1.0 - a0.0) + if forward { 0.0 } else { std::f64::consts::PI };
                        put_world(k, sp, kinds[kind], wx, wy, h + 2.94, tyaw, pitch, bh(i, j, salt + 700), id, tile);
                    }
                }
                s += if a { 16.0 + 30.0 * bu(i, j, salt + 800) } else { 25.0 + 50.0 * bu(i, j, salt + 800) };
                n += 1;
            }
        }
    }
}

fn ground(k: usize, terrain: &Terrain, x: f64, y: f64) -> f64 {
    let (la, lo) = to_lat_lon(k, x, y);
    terrain.height(la, lo).max(0.0) as f64
}

/// Parked cars: in the stalls of block (i, j)'s parking lots (the bays globe.rchit cityGround
/// draws) and in the houses' driveways. Never under a building.
#[allow(clippy::too_many_arguments)]
fn parked(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile, placed: &[Placed]) {
    let (kinds, _) = car_kinds(&sp.buildings);
    if kinds.len() < 6 {
        return;
    }
    let (x0, y0, w, h) = interior(i, j);
    let z = block_zone(k, i, j);
    let free = |x: f64, y: f64| !placed.iter().any(|p| (x - p.x).abs() < p.hx + 1.2 && (y - p.y).abs() < p.hy + 1.2);
    let mut n = 0u32;
    if parking_block(z, i, j) {
        // stalls of 2.6 m either side of 7 m aisles, rows every 18 m (from 2 m in)
        let mut row = 0;
        loop {
            let base = 2.0 + 18.0 * row as f64;
            if base + 15.25 + 2.5 > h - 2.2 && base + 2.75 + 2.5 > h - 2.2 {
                break;
            }
            for (dy, flip) in [(2.75, 0.0), (15.25, std::f64::consts::PI)] {
                let by = base + dy;
                if by < 4.6 || by > h - 4.6 {
                    continue;
                }
                let stalls = ((w - 4.4) / 2.6).floor() as i64;
                for st in 0..stalls {
                    n += 1;
                    if bu(i, j, 20_000 + n) > 0.62 {
                        continue;
                    }
                    let bx = 2.2 + (st as f64 + 0.5) * 2.6 + (w - 4.4 - stalls as f64 * 2.6) * 0.5;
                    let (x, y) = (x0 + bx, y0 + by);
                    if !free(x, y) || !buildable(k, terrain, x, y) || near_water(k, terrain, x, y, if z >= 2 { WATERFRONT } else { 12.0 }) {
                        continue;
                    }
                    let kind = (bh(i, j, 21_000 + n) % 5) as usize;
                    let yaw = std::f64::consts::FRAC_PI_2 + flip + (bu(i, j, 22_000 + n) - 0.5) * 0.08;
                    put_at(k, sp, kinds[kind], x, y, ground(k, terrain, x, y), yaw, bh(i, j, 23_000 + n), id, tile);
                }
            }
            row += 1;
        }
    } else if z == 0 {
        let nl = (w / HOUSE_LOT).floor().max(1.0) as usize;
        for r in 0..2 {
            for l in 0..nl {
                let lot = (r * nl + l) as u32;
                let (ls, lw) = house_lot(i, j, r, l, nl, w);
                let right = bu(i, j, 30 + lot) < 0.5;
                let u = if right { lw - 3.0 } else { 3.0 };
                for (c, v) in [(0u32, 3.4), (1, 9.0)] {
                    if bu(i, j, 24_000 + lot * 2 + c) > if c == 0 { 0.65 } else { 0.3 } {
                        continue;
                    }
                    let (x, y) = (x0 + ls + u, if r == 0 { y0 + v } else { y0 + h - v });
                    if !free(x, y) || !buildable(k, terrain, x, y) || near_water(k, terrain, x, y, 12.0) {
                        continue;
                    }
                    // nose in towards the house
                    let yaw = if r == 0 { std::f64::consts::FRAC_PI_2 } else { -std::f64::consts::FRAC_PI_2 };
                    let kind = (bh(i, j, 25_000 + lot * 2 + c) % 5) as usize;
                    put_at(k, sp, kinds[kind], x, y, ground(k, terrain, x, y), yaw, bh(i, j, 26_000 + lot * 2 + c), id, tile);
                }
            }
        }
    }
}

/// Place archetype `r` at plane point (x, y), height h, facing `yaw`, if its foot is in tile
/// `id`.
#[allow(clippy::too_many_arguments)]
fn put_at(k: usize, sp: &Species, r: &ArchRef, x: f64, y: f64, h: f64, yaw: f64, seed: u32, id: TileId, tile: &mut TreeTile) {
    let Some(d) = in_tile(k, x, y, id) else { return };
    if tile.recs.len() >= MAX_PER_TILE {
        return;
    }
    let rows = frame_rows(d, tile.center, h, yaw, 1.0);
    push_rec(tile, rows, super::forest::rec_data(r.variant, (1 + seed % 8190) << 8), &sp.infos[r.variant]);
}

const BOAT_CELL: f64 = 130.0;

/// Width of the waterfront park along the water, kept free of buildings (globe.rchit cityGround).
const WATERFRONT: f64 = 32.0;

/// Is there sea-level water within `r` m of the plan point (eight directions and the point)?
fn near_water(k: usize, terrain: &Terrain, x: f64, y: f64, r: f64) -> bool {
    (0..8).any(|n| {
        let a = n as f64 * std::f64::consts::FRAC_PI_4;
        water_at(k, terrain, x + r * a.cos(), y + r * a.sin())
    }) || water_at(k, terrain, x, y)
}

/// Marinas off the waterfront of block (i, j) (the city's blocks other than houses): where the
/// water reaches out beyond an edge of the block, a walkway runs along the edge 14 m out, finger
/// docks off it every 9 m, and boats moored either side of most fingers.
#[allow(clippy::too_many_arguments)]
fn marinas(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile, dock: &ArchRef, boats: &[&ArchRef]) {
    if boats.len() < 3 {
        return;
    }
    let (x0, y0, w, h) = interior(i, j);
    // edges: start, direction along, outward normal, length
    let edges = [
        ((x0, y0), (1.0, 0.0), (0.0, -1.0), w),
        ((x0 + w, y0), (0.0, 1.0), (1.0, 0.0), h),
        ((x0 + w, y0 + h), (-1.0, 0.0), (0.0, 1.0), w),
        ((x0, y0 + h), (0.0, -1.0), (-1.0, 0.0), h),
    ];
    for (e, &((sx, sy), (ax, ay), (nx, ny), len)) in edges.iter().enumerate() {
        if bu(i, j, 9800 + e as u32) > 0.25 {
            continue;
        }
        let mut t = 6.0;
        let mut n = 0u32;
        while t < len - 6.0 {
            let (bx, by) = (sx + ax * t, sy + ay * t);
            n += 1;
            t += 9.0;
            // the walkway's place and the fingers' far ends must be water
            // (the block's own edge must be land: blocks out in the bay have no marinas)
            if water_at(k, terrain, bx - nx * 3.0, by - ny * 3.0) || water_at(k, terrain, bx - nx * 15.0, by - ny * 15.0) {
                continue;
            }
            let wx = (bx + nx * 14.0, by + ny * 14.0);
            if !water_at(k, terrain, wx.0, wx.1) || !water_at(k, terrain, bx + nx * 28.0, by + ny * 28.0) || !water_at(k, terrain, bx + nx * 70.0, by + ny * 70.0) {
                continue;
            }
            let salt = 10_000 + e as u32 * 1000 + n;
            let along = ay.atan2(ax);
            let out = ny.atan2(nx);
            // the walkway: a dock lying along the edge (its 13 m from x = 0)
            put_boat(k, sp, dock, wx.0 - ax * 4.5, wx.1 - ay * 4.5, along, bh(i, j, salt), id, tile);
            // the finger, out from the walkway
            put_boat(k, sp, dock, wx.0 + nx * 1.4, wx.1 + ny * 1.4, out, bh(i, j, salt + 1), id, tile);
            for side in [-1.0f64, 1.0] {
                if bu(i, j, salt + 2 + (side > 0.0) as u32) > 0.8 {
                    continue;
                }
                let kind = if bu(i, j, salt + 4 + (side > 0.0) as u32) < 0.6 { 0 } else if bu(i, j, salt + 6) < 0.9 { 1 } else { 2 };
                let r = boats[kind];
                let off = 1.4 + r.size[1] as f64 * 0.5 + 0.3;
                let reach = 1.4 + r.size[0] as f64 * 0.5 + 0.5;
                let (px, py) = (wx.0 + nx * reach + ax * side * off, wx.1 + ny * reach + ay * side * off);
                if water_at(k, terrain, px + nx * r.size[0] as f64 * 0.5, py + ny * r.size[0] as f64 * 0.5) {
                    put_boat(k, sp, r, px, py, out + if bu(i, j, salt + 8) < 0.5 { 0.0 } else { std::f64::consts::PI }, bh(i, j, salt + 9), id, tile);
                }
            }
        }
    }
}

/// The boat archetypes (runabout, cruiser, yacht) and the dock, in that order.
fn boat_kinds(archs: &[ArchRef]) -> (Vec<&ArchRef>, Option<&ArchRef>) {
    (archs.iter().filter(|a| a.class == Class::Boat).collect(), archs.iter().find(|a| a.class == Class::Dock))
}

/// Water at sea level (the bay, the river, the canals). Ponds above it are land in a city
/// (globe.rchit: the land cover's ponds among the blocks are mostly mapping noise).
fn water_at(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    let (la, lo) = to_lat_lon(k, x, y);
    sea_level_water(terrain, la, lo)
}

/// Mapped water whose surface is at sea level, decided as the terrain decides a water level
/// (tiles.rs water_levels: the lower quartile of the mapped water's heights around, under 1 m
/// is the sea; globe.rchit makes the water above it land in a city).
fn sea_level_water(terrain: &Terrain, la: f64, lo: f64) -> bool {
    if terrain.cover.class_group(la, lo) != Some(lc::WATER) {
        return false;
    }
    // (kept per thread by the point quantised to ~4 m: the corner checks ask again and again)
    let key = ((la * 25_000.0).round() as i64, (lo * 25_000.0).round() as i64);
    if let Some(v) = SEA.with(|c| c.borrow().get(&key).copied()) {
        return v;
    }
    let v = sea_level_water_at(terrain, la, lo);
    SEA.with(|c| {
        let mut c = c.borrow_mut();
        if c.len() > 1 << 21 {
            c.clear();
        }
        c.insert(key, v);
    });
    v
}

thread_local! {
    /// the tile being grown: its box in the plan (in_tile's quick test)
    static TILE_BOX: std::cell::Cell<(f64, f64, f64, f64)> = const { std::cell::Cell::new((f64::MIN, f64::MAX, f64::MIN, f64::MAX)) };
    static SEA: std::cell::RefCell<std::collections::HashMap<(i64, i64), bool>> = Default::default();
}

fn sea_level_water_at(terrain: &Terrain, la: f64, lo: f64) -> bool {
    let (dla, dlo) = (12.0 / 110_540.0, 12.0 / (111_320.0 * la.to_radians().cos()));
    let mut h: Vec<f32> = Vec::with_capacity(25);
    for a in -2..=2 {
        for b in -2..=2 {
            let (pa, po) = (la + a as f64 * dla, lo + b as f64 * dlo);
            if terrain.cover.class_group(pa, po) == Some(lc::WATER) {
                h.push(terrain.height(pa, po));
            }
        }
    }
    h.sort_by(|a, b| a.total_cmp(b));
    // drawn as water only where the ground is under that level (tiles.rs: the drawn water is
    // mapped water whose ground lies below its level, and the 30 m data puts the sea at 0 m
    // exactly; a pond above sea level is land in a city)
    h[h.len() / 4] < 1.0 && terrain.height(la, lo) < 0.6
}

/// May a house stand here? As `buildable`, but mapped water counts as land wherever most of
/// it round about is raised above 0.1 m: the narrow islands' backs, which the terrain draws as
/// land (the sea is at exactly 0 m in the 30 m data), and which the strict test leaves empty.
fn house_ground(k: usize, terrain: &Terrain, x: f64, y: f64) -> bool {
    if buildable(k, terrain, x, y) {
        return true;
    }
    let (wx, wy) = to_world(x, y);
    if on_way(wx, wy, 1.0) {
        return false;
    }
    let (la, lo) = to_lat_lon(k, x, y);
    if terrain.cover.class_group(la, lo) != Some(lc::WATER) {
        return false;
    }
    let (dla, dlo) = (12.0 / 110_540.0, 12.0 / (111_320.0 * la.to_radians().cos()));
    let mut raised = 0;
    for a in -2..=2 {
        for b in -2..=2 {
            if terrain.height(la + a as f64 * dla, lo + b as f64 * dlo) >= 0.1 {
                raised += 1;
            }
        }
    }
    raised >= 13
}

/// Place a boat (variant of `r`) at plane point (x, y), bow towards `yaw` (from east towards
/// north), floating at sea level, if its foot is in tile `id`.
#[allow(clippy::too_many_arguments)]
fn put_boat(k: usize, sp: &Species, r: &ArchRef, x: f64, y: f64, yaw: f64, seed: u32, id: TileId, tile: &mut TreeTile) {
    let Some(d) = in_tile(k, x, y, id) else { return };
    if tile.recs.len() >= MAX_PER_TILE {
        return;
    }
    let rows = frame_rows(d, tile.center, 0.0, yaw, 1.0);
    push_rec(tile, rows, super::forest::rec_data(r.variant, (1 + seed % 8190) << 8), &sp.infos[r.variant]);
}

/// A boat on open water in cell (a, b), clear of the shore: runabouts and cruisers near
/// (finest tiles), the yachts also a level out.
#[allow(clippy::too_many_arguments)]
fn open_water_boat(k: usize, terrain: &Terrain, sp: &Species, a: i64, b: i64, lvl: u8, id: TileId, tile: &mut TreeTile) {
    let (boats, _) = boat_kinds(&sp.buildings);
    let under: Vec<&ArchRef> = sp.buildings.iter().filter(|a| a.class == Class::Underway).collect();
    if boats.len() < 3 || bu(a, b, 9000) > 0.5 {
        return;
    }
    let kind = if bu(a, b, 9001) < 0.5 { 0 } else if bu(a, b, 9001) < 0.85 { 1 } else { 2 };
    // (each tile level covers its own band of distance: the yachts are in the next level's tiles
    // too, so they are still seen beyond the finest tiles' 6 km)
    if lvl == 1 && kind != 2 {
        return;
    }
    let (x, y) = ((a as f64 + 0.15 + 0.7 * bu(a, b, 9002)) * BOAT_CELL, (b as f64 + 0.15 + 0.7 * bu(a, b, 9003)) * BOAT_CELL);
    let yaw = bu(a, b, 9004) * std::f64::consts::TAU;
    // most are under way, with their wake
    let r = if under.len() == 3 && bu(a, b, 9006) < 0.75 { under[kind] } else { boats[kind] };
    let half = r.size[0] as f64 * 0.5 + 25.0;
    let (c, s) = (yaw.cos(), yaw.sin());
    let clear = [(0.0, 0.0), (half, 0.0), (-half, 0.0), (0.0, 20.0), (0.0, -20.0)]
        .iter()
        .all(|&(u, v)| water_at(k, terrain, x + u * c - v * s, y + u * s + v * c));
    if clear {
        put_boat(k, sp, r, x, y, yaw, bh(a, b, 9005), id, tile);
    }
}

/// Docks behind the waterfront houses of block (i, j): where the land beyond a house lot's back
/// line is water, a timber dock runs out from the lot, a boat moored alongside most of them.
#[allow(clippy::too_many_arguments)]
fn docks(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile, placed: &[Placed]) {
    let (boats, dock) = boat_kinds(&sp.buildings);
    let Some(dock) = dock else { return };
    if block_zone(k, i, j) != 0 {
        marinas(k, terrain, sp, i, j, id, tile, dock, &boats);
        return;
    }
    if placed.is_empty() {
        return;
    }
    let (x0, y0, w, h) = interior(i, j);
    let n = (w / HOUSE_LOT).floor().max(1.0) as usize;
    for row in 0..2 {
        for l in 0..n {
            let lot = (row * n + l) as u32;
            let (ls, lw) = house_lot(i, j, row, l, n, w);
            let u = ls + lw * (0.3 + 0.4 * bu(i, j, 9100 + lot));
            // the lot's back line, and outwards (away from its street)
            let (yb, out) = if row == 0 { (y0 + h * 0.5, 1.0) } else { (y0 + h * 0.5, -1.0) };
            let x = x0 + u;
            // a house on this lot, land at the lot, water beyond the back line
            let has_house = placed.iter().any(|p| p.hx > 2.0 && (p.x - (x0 + ls + lw * 0.5)).abs() < lw * 0.5 && (p.y - yb).abs() < h * 0.5 && (p.y - yb) * out < 0.0);
            if !has_house || !water_at(k, terrain, x, yb + out * 6.0) || !water_at(k, terrain, x, yb + out * 14.0) {
                continue;
            }
            // the dock starts at the shore: walk back from the water to the first land
            let mut s = 6.0;
            while s > -10.0 && water_at(k, terrain, x, yb + out * s) {
                s -= 2.0;
            }
            let ys = yb + out * (s + 1.0);
            let yaw = if out > 0.0 { std::f64::consts::FRAC_PI_2 } else { -std::f64::consts::FRAC_PI_2 };
            put_boat(k, sp, dock, x, ys, yaw, bh(i, j, 9200 + lot), id, tile);
            if boats.len() >= 2 && bu(i, j, 9300 + lot) < 0.75 {
                let kind = if bu(i, j, 9400 + lot) < 0.55 { 0 } else { 1 };
                let r = boats[kind];
                let side = if bu(i, j, 9500 + lot) < 0.5 { 1.0 } else { -1.0 };
                let bx = x + side * (1.4 + r.size[1] as f64 * 0.5 + 0.4);
                let by = ys + out * (7.0 + r.size[0] as f64 * 0.1);
                if water_at(k, terrain, bx, by + out * r.size[0] as f64 * 0.5) {
                    // bow out or in
                    let flip = if bu(i, j, 9600 + lot) < 0.5 { 0.0 } else { std::f64::consts::PI };
                    put_boat(k, sp, r, bx, by, yaw + flip, bh(i, j, 9700 + lot), id, tile);
                }
            }
        }
    }
}

/// Palms along the sidewalks on the west and south sides of block (i, j)'s street lines (each
/// street line belongs to one block column or row: the street at x = i BX and the one at
/// y = j BY), both sides of the street, one every ~12 m near the kerb, on built-up dry land;
/// whole streets have palms or none. Those whose foot lies in tile `id`.
fn street_palms(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile) {
    // (x, y, salt, palm?) : two streets in three are palm-lined, the rest have shade trees
    let mut spots = Vec::new();
    // the north-south street at x = i BX, along this block's y span
    {
        let palm = bh(i, 0, 50) % 3 != 0;
        let a = art_x(i);
        let off = half_width(a) - sidewalk(a) + 1.1;
        let (ys, ye) = (line_y(j) + half_width(art_y(j)) + 4.0, line_y(j + 1) - half_width(art_y(j + 1)) - 4.0);
        let n = ((ye - ys) / if palm { 12.0 } else { 15.0 }).floor().max(1.0) as usize;
        for s in 0..=n {
            let y = ys + (ye - ys) * s as f64 / n as f64;
            spots.push((line_x(i) - off, y, s as u32, palm));
            spots.push((line_x(i) + off, y, 100 + s as u32, palm));
        }
    }
    // the east-west street at y = j BY, along this block's x span
    {
        let palm = bh(0, j, 51) % 3 != 0;
        let a = art_y(j);
        let off = half_width(a) - sidewalk(a) + 1.1;
        let (xs, xe) = (line_x(i) + half_width(art_x(i)) + 4.0, line_x(i + 1) - half_width(art_x(i + 1)) - 4.0);
        let n = ((xe - xs) / if palm { 12.0 } else { 15.0 }).floor().max(1.0) as usize;
        for s in 0..=n {
            let x = xs + (xe - xs) * s as f64 / n as f64;
            spots.push((x, line_y(j) - off, 200 + s as u32, palm));
            spots.push((x, line_y(j) + off, 300 + s as u32, palm));
        }
    }
    for (x, y, n, palm) in spots {
        if bu(i, j, 1000 + n) > 0.85 {
            continue;
        }
        let Some(d) = in_tile(k, x, y, id) else { continue };
        let (lat, lon) = lat_lon(d);
        let built = built_share(terrain, lat, lon, 30.0);
        if built < 0.25 || !buildable(k, terrain, x, y) || mapped_water(k, terrain, x, y) {
            continue;
        }
        if tile.recs.len() >= MAX_PER_TILE {
            return;
        }
        let list = if palm || sp.city_trees.is_empty() { &sp.palms } else { &sp.city_trees };
        let vid = list[(bh(i, j, 2000 + n) as usize) % list.len()];
        let sc = if palm { 0.85 + 0.35 * bu(i, j, 4000 + n) } else { 0.55 + 0.3 * bu(i, j, 4000 + n) };
        let rows = frame_rows(d, tile.center, terrain.height(lat, lon).max(0.0) as f64 - 0.1, bu(i, j, 3000 + n) * std::f64::consts::TAU, sc);
        push_rec(tile, rows, super::forest::rec_data(vid, (1 + bh(i, j, 5000 + n) % 8190) << 8), &sp.infos[vid]);
    }
}

/// Trees on the lots of block (i, j), where globe.rchit cityGround leaves room for them: in the
/// houses' front yards (on the side away from the driveway) and back yards (beyond the pools),
/// palms along the planted edges of the parking lots, palms in the plazas' planters. Never under
/// a building; those whose foot lies in tile `id`.
#[allow(clippy::too_many_arguments)]
fn lot_trees(k: usize, terrain: &Terrain, sp: &Species, i: i64, j: i64, id: TileId, tile: &mut TreeTile, placed: &[Placed]) {
    let (x0, y0, w, h) = interior(i, j);
    let z = block_zone(k, i, j);
    // (x, y, broad crown?, salt)
    let mut spots: Vec<(f64, f64, bool, u32)> = Vec::new();
    if z == 0 {
        let n = (w / HOUSE_LOT).floor().max(1.0) as usize;
        for row in 0..2 {
            for l in 0..n {
                let lot = (row * n + l) as u32;
                let (ls, lw) = house_lot(i, j, row, l, n, w);
                let right = bu(i, j, 30 + lot) < 0.5;
                let at = |u: f64, v: f64| (x0 + ls + u, if row == 0 { y0 + v } else { y0 + h - v });
                if bu(i, j, 3100 + lot) < 0.85 {
                    let (x, y) = at(if right { 2.6 } else { lw - 2.6 }, 2.8);
                    spots.push((x, y, bu(i, j, 3200 + lot) < 0.4, 3300 + lot));
                }
                let backs = 2 + (bu(i, j, 3400 + lot) * 2.5) as u32;
                for t in 0..backs {
                    let u = 3.0 + (lw - 6.0) * bu(i, j, 3500 + lot * 4 + t);
                    let (x, y) = at(u, h * 0.5 - 3.5 - 2.0 * bu(i, j, 3600 + lot * 4 + t));
                    spots.push((x, y, bu(i, j, 3700 + lot * 4 + t) < 0.7, 3800 + lot * 4 + t));
                }
            }
        }
    } else if parking_block(z, i, j) {
        // the planted strip round a parking lot (2.2 m wide)
        let per = 2.0 * (w + h);
        let n = (per / 15.0).floor() as u32;
        for t in 0..n {
            if bu(i, j, 4100 + t) > 0.5 {
                continue;
            }
            let s = (t as f64 + 0.5) / n as f64 * per;
            let (u, v) = if s < w {
                (s, 1.1)
            } else if s < w + h {
                (w - 1.1, s - w)
            } else if s < 2.0 * w + h {
                (2.0 * w + h - s, h - 1.1)
            } else {
                (1.1, per - s)
            };
            spots.push((x0 + u, y0 + v, false, 4200 + t));
        }
    } else {
        // plazas: shade trees on the lawn panels (globe.rchit: lawn between 4 m paths every
        // 18 x 15 m), a broad crown in most, a palm in some
        let (nx, ny) = ((w / 18.0).floor() as i64, (h / 15.0).floor() as i64);
        for a in 0..nx {
            for b in 0..ny {
                let salt = 4400 + (a * 31 + b) as u32;
                spots.push((x0 + a as f64 * 18.0 + 8.0, y0 + b as f64 * 15.0 + 7.5, bu(i, j, salt + 9) < 0.8, salt));
                if bu(i, j, salt + 7) < 0.7 {
                    spots.push((x0 + a as f64 * 18.0 + 14.5, y0 + b as f64 * 15.0 + 12.0, true, salt + 20_000));
                }
            }
        }
    }
    // clumps of broad crowns between the buildings: three to six per block that is not a car
    // park, eight to fourteen trees each, a canopy that hides the ground (the houses' yards
    // have theirs above)
    if z >= 1 && !parking_block(z, i, j) {
        let clumps = 3 + (bu(i, j, 5100) * 4.0) as u32;
        for cl in 0..clumps {
            let (cx, cy) = (x0 + 8.0 + (w - 16.0) * bu(i, j, 5200 + cl), y0 + 8.0 + (h - 16.0) * bu(i, j, 5300 + cl));
            let n = 8 + (bu(i, j, 5400 + cl) * 7.0) as u32;
            for t in 0..n {
                let a = bu(i, j, 5500 + cl * 16 + t) * std::f64::consts::TAU;
                let r = 2.0 + 11.0 * bu(i, j, 5600 + cl * 16 + t).sqrt();
                spots.push((cx + r * a.cos(), cy + r * a.sin(), true, 5700 + cl * 16 + t));
            }
        }
    }
    // groves: in the walk-up and mid-rise blocks that are not car parks, about half of the
    // block's 30 m cells are planted solid (a crown every 7-8 m, the ground under them hidden,
    // as the reference's canopy between the buildings); the buildings keep their own ground
    // (and in the house blocks: the yards' own shade trees, the canopy of Miami's older
    // neighbourhoods; a crown that would stand on a house, its pool or its drive is skipped)
    if z <= 2 && !parking_block(z, i, j) {
        let (cn, cm) = ((w / 30.0).ceil().max(1.0) as u32, (h / 30.0).ceil().max(1.0) as u32);
        let (cw, ch) = (w / cn as f64, h / cm as f64);
        for b in 0..cm {
            for a in 0..cn {
                let cell = b * 16 + a;
                // (a block with little or nothing built, a park, is planted thickest)
                let open = placed.iter().map(|p| p.hx * p.hy * 4.0).sum::<f64>() < 0.12 * w * h;
                // (built-up blocks keep their ground built: car parks, courts, palms; the canopy is
                // the parks', the house blocks' and the islands')
                if bu(i, j, 9000 + cell) > if open { 0.75 } else if z == 0 { 0.5 } else if z == 2 { 0.22 } else { 0.32 } {
                    continue;
                }
                let (gn, gm) = ((cw / 6.5).floor().max(1.0) as u32, (ch / 6.5).floor().max(1.0) as u32);
                for v in 0..gm {
                    for u in 0..gn {
                        let t = cell * 64 + v * 8 + u;
                        let px = x0 + a as f64 * cw + (u as f64 + 0.2 + 0.6 * bu(i, j, 9100 + t)) * cw / gn as f64;
                        let py = y0 + b as f64 * ch + (v as f64 + 0.2 + 0.6 * bu(i, j, 9200 + t)) * ch / gm as f64;
                        if z == 0 {
                            // (off the front yards, where the drives are: 7 m back from either street)
                            let back = (py - y0).min(y0 + h - py);
                            if back < FRONT_YARD + 3.0 {
                                continue;
                            }
                        }
                        spots.push((px, py, bu(i, j, 9300 + t) < 0.85, 100_000 + t));
                    }
                }
            }
        }
    }
    // the waterfront: palms and broad crowns along every edge of the block that the water
    // comes within 12 m of (the canal banks, the bay shore), every ~8 m
    {
        let per = 2.0 * (w + h);
        let n = (per / 8.0).floor() as u32;
        for t in 0..n {
            let s = (t as f64 + 0.5) / n as f64 * per;
            let (u, v, nx, ny) = if s < w {
                (s, 1.5, 0.0, -1.0)
            } else if s < w + h {
                (w - 1.5, s - w, 1.0, 0.0)
            } else if s < 2.0 * w + h {
                (2.0 * w + h - s, h - 1.5, 0.0, 1.0)
            } else {
                (1.5, per - s, -1.0, 0.0)
            };
            let (x, y) = (x0 + u, y0 + v);
            // water just beyond this edge (past the street) or right here at a lot's back
            let near = water_at(k, terrain, x + nx * 12.0, y + ny * 12.0) || water_at(k, terrain, x - nx * 6.0 + ny * 6.0, y - ny * 6.0 + nx * 6.0);
            if near && bu(i, j, 8000 + t) < 0.8 {
                spots.push((x, y, bu(i, j, 8100 + t) < 0.35, 8200 + t));
            }
        }
    }
    for (x, y, broad, salt) in spots {
        if placed.iter().any(|p| (x - p.x).abs() < p.hx + 1.5 && (y - p.y).abs() < p.hy + 1.5) {
            continue;
        }
        let list = if broad && !sp.city_trees.is_empty() { &sp.city_trees } else { &sp.palms };
        let Some(d) = in_tile(k, x, y, id) else { continue };
        // (trees stand in the waterfront park too: the shore's own canopy)
        let (lat, lon) = lat_lon(d);
        // (the groves grow on the open ground too, parks and lawns: only off the water)
        let grove = salt >= 100_000;
        if !buildable(k, terrain, x, y) || (!grove && built_share(terrain, lat, lon, 30.0) < 0.2) {
            continue;
        }
        if tile.recs.len() >= MAX_PER_TILE {
            return;
        }
        let vid = list[(bh(i, j, salt) as usize) % list.len()];
        // (a grove's crowns grow big and meet: the canopy closes over the ground)
        let sc = if grove && broad { 0.95 + 0.4 * bu(i, j, salt + 50_000) } else if broad { 0.7 + 0.4 * bu(i, j, salt + 50_000) } else { 0.85 + 0.35 * bu(i, j, salt + 50_000) };
        // (the temperate stand-ins grew up in forests, tall and narrow: spread wider and lower,
        // a city's live oaks, figs and mahoganies, domed crowns that merge into a carpet)
        let (across, up_sc) = if broad && list.as_ptr() == sp.city_trees.as_ptr() { if grove { (sc * 1.45, sc * 0.8) } else { (sc * 1.3, sc * 0.88) } } else { (sc, sc) };
        let rows = frame_rows_xy(d, tile.center, terrain.height(lat, lon).max(0.0) as f64 - 0.1, bu(i, j, salt + 60_000) * std::f64::consts::TAU, across, up_sc);
        push_rec(tile, rows, super::forest::rec_data(vid, (1 + bh(i, j, salt + 70_000) % 8190) << 8), &sp.infos[vid]);
    }
}

/// Object -> tile rows for something standing at direction `d` at height `h`, turned `yaw`
/// from east towards north, scaled.
fn frame_rows(d: DVec3, center: DVec3, h: f64, yaw: f64, sc: f64) -> [[f64; 4]; 3] {
    frame_rows_xy(d, center, h, yaw, sc, sc)
}

/// As frame_rows, scaled `across` horizontally and `up` vertically (a crown spread wider).
fn frame_rows_xy(d: DVec3, center: DVec3, h: f64, yaw: f64, across: f64, up_sc: f64) -> [[f64; 4]; 3] {
    // (turned with its street: the plan's axes bend with the warp)
    let (lat, lon) = lat_lon(d);
    let yaw = yaw + city_at(lat, lon).map(|(_, x, y)| twist(x, y)).unwrap_or(0.0);
    let up = d;
    let east = DVec3::Z.cross(up).normalize();
    let north = up.cross(east);
    let x = east * yaw.cos() + north * yaw.sin();
    let z = x.cross(up);
    let (x, y, z) = (x * across, up * up_sc, z * across);
    let t = d * (R_EARTH + h) - center;
    [[x.x, y.x, z.x, t.x], [x.y, y.y, z.y, t.y], [x.z, y.z, z.z, t.z]]
}

fn push_rec(tile: &mut TreeTile, rows: [[f64; 4]; 3], data: u32, info: &ImpostorInfo) {
    let mut rec = [0u32; REC_WORDS];
    for (ri, row) in rows.iter().enumerate() {
        for (ci, v) in row.iter().enumerate() {
            rec[ri * 4 + ci] = (*v as f32).to_bits();
        }
    }
    rec[12] = data;
    let (bmin, bmax) = (info.bmin, info.bmax);
    let mut lo = [f32::MAX; 3];
    let mut hi = [f32::MIN; 3];
    for c in 0..8 {
        let q = [
            if c & 1 == 0 { bmin[0] } else { bmax[0] } as f64,
            if c & 2 == 0 { bmin[1] } else { bmax[1] } as f64,
            if c & 4 == 0 { bmin[2] } else { bmax[2] } as f64,
        ];
        for (k, row) in rows.iter().enumerate() {
            let v = (row[0] * q[0] + row[1] * q[1] + row[2] * q[2] + row[3]) as f32;
            lo[k] = lo[k].min(v);
            hi[k] = hi[k].max(v);
        }
    }
    tile.recs.push(rec);
    tile.aabbs.push([lo[0], lo[1], lo[2], hi[0], hi[1], hi[2]]);
}

/// Thread time spent in the city's plan (stats_line): grow, streets, way items, blocked, block.
pub static CITY_NS: [std::sync::atomic::AtomicU64; 5] = [const { std::sync::atomic::AtomicU64::new(0) }; 5];
struct Timer(usize, std::time::Instant);
impl Drop for Timer {
    fn drop(&mut self) {
        CITY_NS[self.0].fetch_add(self.1.elapsed().as_nanos() as u64, std::sync::atomic::Ordering::Relaxed);
    }
}
